export default Object.freeze({"en":{"copyLanguage":"en","name":"Momentum Calculator","title":"Momentum Calculator Free | UsefulVerse","description":"Calculate one-dimensional momentum or model a two-object collision with signed speeds. Free and local.","intro":"Find total momentum for two objects moving along one line, or estimate their speeds after a collision. Set each direction with a positive or negative velocity and choose a coefficient of restitution from 0 to 1.","howQuestion":"How do you calculate momentum and collision speeds?","howAnswer":"Momentum is mass times velocity, p = mv, and the total is the signed sum for both objects. For a one-dimensional collision, this calculator uses the coefficient of restitution to estimate each final velocity. For example, equal 1 kg masses moving at +2 m/s and −1 m/s exchange speeds in an ideal elastic collision, while total momentum remains 1 kg·m/s.","privacyQuestion":"Are my values uploaded?","privacyAnswer":"No. The calculation runs in this browser; the values are not uploaded or saved.","fields":{"mode":"Calculation","momentumMode":"Total momentum only","collisionMode":"Model a collision","mass1":"Object 1 mass","mass2":"Object 2 mass","massUnit":"Mass unit","kilograms":"Kilograms (kg)","grams":"Grams (g)","tonnes":"Metric tonnes (t)","velocity1":"Object 1 initial velocity","velocity2":"Object 2 initial velocity","speedUnit":"Velocity unit","metersPerSecond":"Meters per second (m/s)","kilometersPerHour":"Kilometers per hour (km/h)","feetPerSecond":"Feet per second (ft/s)","restitution":"Coefficient of restitution (0–1)","accuracyNote":"One-dimensional classical model. Positive and negative velocities show direction. Collisions are treated as isolated: no external impulse, rotation, deformation detail or relativistic effects are modeled. A value of 1 is ideal elastic; 0 is perfectly inelastic. This is an educational estimate, not an engineering or safety assessment."},"actions":{"calculate":"Calculate","reset":"Clear","copy":"Copy result","example":"Try equal masses colliding","result":"Momentum result"},"messages":{"calculated":"Calculation ready.","checkInputs":"Enter two positive masses, valid signed velocities, supported units, and a restitution value from 0 to 1.","momentumBefore":"Total momentum before collision","kineticEnergyBefore":"Total kinetic energy before collision","finalVelocity1":"Object 1 final velocity","finalVelocity2":"Object 2 final velocity","momentumAfter":"Total momentum after collision","kineticEnergyAfter":"Total kinetic energy after collision","energyLoss":"Kinetic energy converted or lost in the model"},"additionalFaqs":[{"question":"What does a negative velocity mean?","answer":"It means the object moves in the opposite direction from the positive direction you chose. Keep the sign when entering both velocities; it affects total momentum and the collision result."},{"question":"What does the coefficient of restitution mean?","answer":"It describes the relative separating speed after a one-dimensional impact compared with the approaching speed. Zero models a perfectly inelastic collision; one models an ideal elastic collision. Real materials can vary with impact conditions."},{"question":"Is momentum conserved in every collision?","answer":"Total momentum is conserved in this model when the two-object system has no net external impulse. The calculator shows values before and after so you can compare them."},{"question":"Does this calculator cover angled or rotating collisions?","answer":"No. It models motion on one straight line only. It does not calculate angles, rotation, object shape, sound, heat details or deformation."}],"localizationStatus":"approved","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"es":{"copyLanguage":"es","name":"Calculadora de momento","title":"Calculadora de momento gratis | UsefulVerse","description":"Calcula el momento total y las velocidades tras un choque en una dimensión. Gratis y todo se calcula en tu navegador.","intro":"Encuentra el momento total de dos objetos que se mueven a lo largo de una línea o estima sus velocidades después de una colisión. \nEstablezca cada dirección con una velocidad positiva o negativa y elija un coeficiente de restitución de 0 a 1.","howQuestion":"¿Cómo se calcula el impulso y las velocidades de colisión?","howAnswer":"El momento es la masa multiplicada por la velocidad, p = mv, y el total es la suma con signo de ambos objetos. \nPara una colisión unidimensional, esta calculadora utiliza el coeficiente de restitución para estimar cada velocidad final. \nPor ejemplo, masas iguales de 1 kg que se mueven a +2 m/s y −1 m/s intercambian velocidades en una colisión elástica ideal, mientras que el momento total sigue siendo de 1 kg·m/s.","privacyQuestion":"¿Están subidos mis valores?","privacyAnswer":"No. El cálculo se ejecuta en este navegador; \nlos valores no se cargan ni se guardan.","fields":{"mode":"Cálculo","momentumMode":"Solo impulso total","collisionMode":"Modelar una colisión","mass1":"Objeto 1 masa","mass2":"Objeto 2 masa","massUnit":"Unidad de masa","kilograms":"Kilogramos (kg)","grams":"Gramos (g)","tonnes":"Toneladas métricas (t)","velocity1":"Velocidad inicial del objeto 1","velocity2":"Velocidad inicial del objeto 2","speedUnit":"Unidad de velocidad","metersPerSecond":"Metros por segundo (m/s)","kilometersPerHour":"Kilómetros por hora (km/h)","feetPerSecond":"Pies por segundo (pies/s)","restitution":"Coeficiente de restitución (0–1)","accuracyNote":"Modelo clásico unidimensional. \nLas velocidades positivas y negativas muestran la dirección. \nLas colisiones se tratan como aisladas: no se modelan impulsos externos, rotación, detalles de deformación o efectos relativistas. \nUn valor de 1 es elástico ideal; \n0 es perfectamente inelástico. \nEsta es una estimación educativa, no una evaluación de ingeniería o seguridad."},"actions":{"calculate":"Calcular","reset":"Limpiar","copy":"Copiar resultado","example":"Intenta colisionar masas iguales","result":"Resultado de impulso"},"messages":{"calculated":"Cálculo listo.","checkInputs":"Introduzca dos masas positivas, velocidades con signo válidas, unidades admitidas y un valor de restitución de 0 a 1.","momentumBefore":"Momento total antes de la colisión","kineticEnergyBefore":"Energía cinética total antes de la colisión","finalVelocity1":"Velocidad final del objeto 1","finalVelocity2":"Velocidad final del objeto 2","momentumAfter":"Momento total después de la colisión","kineticEnergyAfter":"Energía cinética total después de la colisión","energyLoss":"Energía cinética convertida o perdida en el modelo"},"additionalFaqs":[{"question":"¿Qué significa una velocidad negativa?","answer":"Significa que el objeto se mueve en la dirección opuesta a la dirección positiva que usted eligió. \nMantener la señal al entrar en ambas velocidades; \nAfecta el impulso total y el resultado de la colisión."},{"question":"¿Qué significa el coeficiente de restitución?","answer":"Describe la velocidad relativa de separación después de un impacto unidimensional en comparación con la velocidad de aproximación. \nZero modela una colisión perfectamente inelástica; \nuno modela una colisión elástica ideal. \nLos materiales reales pueden variar según las condiciones de impacto."},{"question":"¿Se conserva el impulso en cada colisión?","answer":"En este modelo se conserva el impulso total cuando el sistema de dos objetos no tiene impulso externo neto. \nLa calculadora muestra los valores antes y después para que puedas compararlos."},{"question":"¿Esta calculadora cubre colisiones en ángulo o giratorias?","answer":"No. Modela el movimiento en una sola línea recta. \nNo calcula ángulos, rotación, forma de objetos, sonido, detalles térmicos ni deformaciones."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"fr":{"copyLanguage":"fr","name":"Calculateur d'élan","title":"Calculateur d'élan gratuit | UsefulVerse","description":"Calculez la quantité de mouvement unidimensionnelle ou modélisez une collision à deux objets avec des vitesses signées. \nGratuit et local.","intro":"Trouvez l'élan total de deux objets se déplaçant le long d'une ligne ou estimez leur vitesse après une collision. \nDéfinissez chaque direction avec une vitesse positive ou négative et choisissez un coefficient de restitution de 0 à 1.","howQuestion":"Comment calculez-vous l'impulsion et les vitesses de collision ?","howAnswer":"L'élan est la masse multipliée par la vitesse, p = mv, et le total est la somme signée pour les deux objets. \nPour une collision unidimensionnelle, ce calculateur utilise le coefficient de restitution pour estimer chaque vitesse finale. \nPar exemple, des masses égales à 1 kg se déplaçant à des vitesses d'échange de +2 m/s et −1 m/s dans une collision élastique idéale, tandis que l'impulsion totale reste de 1 kg·m/s.","privacyQuestion":"Mes valeurs sont-elles téléchargées ?","privacyAnswer":"Non. Le calcul s'exécute dans ce navigateur ; \nles valeurs ne sont ni téléchargées ni enregistrées.","fields":{"mode":"Calcul","momentumMode":"Moment total uniquement","collisionMode":"Modéliser une collision","mass1":"Objet 1 masse","mass2":"Masse de l'objet 2","massUnit":"Unité de masse","kilograms":"Kilogrammes (kg)","grams":"Grammes (g)","tonnes":"Tonnes métriques (t)","velocity1":"Vitesse initiale de l'objet 1","velocity2":"Vitesse initiale de l'objet 2","speedUnit":"Unité de vitesse","metersPerSecond":"Mètres par seconde (m/s)","kilometersPerHour":"Kilomètres par heure (km/h)","feetPerSecond":"Pieds par seconde (ft/s)","restitution":"Coefficient de restitution (0–1)","accuracyNote":"Modèle classique unidimensionnel. \nLes vitesses positives et négatives indiquent la direction. \nLes collisions sont traitées comme isolées : aucune impulsion externe, rotation, détail de déformation ou effet relativiste n'est modélisé. \nUne valeur de 1 correspond à une élasticité idéale ; \n0 est parfaitement inélastique. \nIl s’agit d’une estimation pédagogique, et non d’une évaluation technique ou de sécurité."},"actions":{"calculate":"Calculer","reset":"Clair","copy":"Copier le résultat","example":"Essayez des collisions de masses égales","result":"Résultat dynamique"},"messages":{"calculated":"Calcul prêt.","checkInputs":"Entrez deux masses positives, des vitesses signées valides, des unités prises en charge et une valeur de restitution comprise entre 0 et 1.","momentumBefore":"Moment total avant collision","kineticEnergyBefore":"Énergie cinétique totale avant collision","finalVelocity1":"Vitesse finale de l'objet 1","finalVelocity2":"Vitesse finale de l'objet 2","momentumAfter":"Moment total après collision","kineticEnergyAfter":"Énergie cinétique totale après collision","energyLoss":"Énergie cinétique convertie ou perdue dans le modèle"},"additionalFaqs":[{"question":"Que signifie une vitesse négative ?","answer":"Cela signifie que l'objet se déplace dans la direction opposée à la direction positive que vous avez choisie. \nGardez le panneau lorsque vous entrez les deux vitesses ; \ncela affecte la quantité de mouvement totale et le résultat de la collision."},{"question":"Que signifie le coefficient de restitution ?","answer":"Il décrit la vitesse relative de séparation après un impact unidimensionnel par rapport à la vitesse d'approche. \nZero modélise une collision parfaitement inélastique ; \non modélise une collision élastique idéale. \nLes matériaux réels peuvent varier en fonction des conditions d'impact."},{"question":"L'élan est-il conservé à chaque collision ?","answer":"L'impulsion totale est conservée dans ce modèle lorsque le système à deux objets n'a pas d'impulsion externe nette. \nLa calculatrice affiche les valeurs avant et après afin que vous puissiez les comparer."},{"question":"Ce calculateur couvre-t-il les collisions angulaires ou rotatives ?","answer":"Non. Il modélise le mouvement sur une seule ligne droite. \nIl ne calcule pas les angles, la rotation, la forme de l'objet, le son, les détails thermiques ou la déformation."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"pt":{"copyLanguage":"pt","name":"Calculadora de Momento","title":"Calculadora de Momentum grátis | UsefulVerse","description":"Calcule o momento unidimensional ou modele uma colisão de dois objetos com velocidades sinalizadas. \nGratuito e local.","intro":"Encontre o momento total de dois objetos que se movem ao longo de uma linha ou estime suas velocidades após uma colisão. \nDefina cada direção com uma velocidade positiva ou negativa e escolha um coeficiente de restituição de 0 a 1.","howQuestion":"Como você calcula o momento e as velocidades de colisão?","howAnswer":"Momentum é massa vezes velocidade, p = mv, e o total é a soma sinalizada para ambos os objetos. \nPara uma colisão unidimensional, esta calculadora utiliza o coeficiente de restituição para estimar cada velocidade final. \nPor exemplo, massas iguais de 1 kg movendo-se a +2 m/s e -1 m/s trocam de velocidade numa colisão elástica ideal, enquanto o momento total permanece 1 kg·m/s.","privacyQuestion":"Meus valores foram carregados?","privacyAnswer":"Não. O cálculo é executado neste navegador; \nos valores não são carregados ou salvos.","fields":{"mode":"Cálculo","momentumMode":"Apenas impulso total","collisionMode":"Modelar uma colisão","mass1":"Objeto 1 massa","mass2":"Objeto 2 massa","massUnit":"Unidade de massa","kilograms":"Quilogramas (kg)","grams":"Gramas (g)","tonnes":"Toneladas métricas (t)","velocity1":"Velocidade inicial do objeto 1","velocity2":"Velocidade inicial do objeto 2","speedUnit":"Unidade de velocidade","metersPerSecond":"Metros por segundo (m/s)","kilometersPerHour":"Quilômetros por hora (km/h)","feetPerSecond":"Pés por segundo (ft/s)","restitution":"Coeficiente de restituição (0–1)","accuracyNote":"Modelo clássico unidimensional. \nAs velocidades positivas e negativas mostram a direção. \nAs colisões são tratadas como isoladas: nenhum impulso externo, rotação, detalhe de deformação ou efeitos relativísticos são modelados. \nUm valor de 1 é elástico ideal; \n0 é perfeitamente inelástico. \nEsta é uma estimativa educacional, não uma avaliação de engenharia ou segurança."},"actions":{"calculate":"Calcular","reset":"Transparente","copy":"Copiar resultado","example":"Tente colidir massas iguais","result":"Resultado dinâmico"},"messages":{"calculated":"Cálculo pronto.","checkInputs":"Insira duas massas positivas, velocidades sinalizadas válidas, unidades suportadas e um valor de restituição de 0 a 1.","momentumBefore":"Momento total antes da colisão","kineticEnergyBefore":"Energia cinética total antes da colisão","finalVelocity1":"Velocidade final do objeto 1","finalVelocity2":"Velocidade final do objeto 2","momentumAfter":"Momento total após colisão","kineticEnergyAfter":"Energia cinética total após colisão","energyLoss":"Energia cinética convertida ou perdida no modelo"},"additionalFaqs":[{"question":"O que significa uma velocidade negativa?","answer":"Significa que o objeto se move na direção oposta à direção positiva que você escolheu. \nMantenha a sinalização ao entrar em ambas as velocidades; \nafeta o momento total e o resultado da colisão."},{"question":"O que significa o coeficiente de restituição?","answer":"Descreve a velocidade de separação relativa após um impacto unidimensional em comparação com a velocidade de aproximação. \nZero modela uma colisão perfeitamente inelástica; \nmodela-se uma colisão elástica ideal. \nOs materiais reais podem variar de acordo com as condições de impacto."},{"question":"O momento linear é conservado em cada colisão?","answer":"O momento total é conservado neste modelo quando o sistema de dois objetos não tem impulso externo líquido. \nA calculadora mostra os valores antes e depois para que você possa compará-los."},{"question":"Esta calculadora cobre colisões angulares ou rotativas?","answer":"Não. Ele modela o movimento apenas em uma linha reta. \nEle não calcula ângulos, rotação, formato do objeto, som, detalhes de calor ou deformação."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"de":{"copyLanguage":"de","name":"Impulsrechner","title":"Momentum-Rechner kostenlos | UsefulVerse","description":"Berechnen Sie einen eindimensionalen Impuls oder modellieren Sie eine Kollision zweier Objekte mit vorzeichenbehafteten Geschwindigkeiten. \nKostenlos und lokal.","intro":"Ermitteln Sie den Gesamtimpuls zweier Objekte, die sich entlang einer Linie bewegen, oder schätzen Sie deren Geschwindigkeit nach einer Kollision ab. \nStellen Sie jede Richtung mit einer positiven oder negativen Geschwindigkeit ein und wählen Sie einen Restitutionskoeffizienten von 0 bis 1.","howQuestion":"Wie berechnet man Impuls und Kollisionsgeschwindigkeit?","howAnswer":"Impuls ist Masse mal Geschwindigkeit, p = mv, und die Summe ist die vorzeichenbehaftete Summe für beide Objekte. \nFür eine eindimensionale Kollision verwendet dieser Rechner den Restitutionskoeffizienten, um jede Endgeschwindigkeit zu schätzen. \nBeispielsweise tauschen gleiche 1-kg-Massen, die sich mit +2 m/s und −1 m/s bewegen, bei einer idealen elastischen Kollision Geschwindigkeiten aus, während der Gesamtimpuls 1 kg·m/s bleibt.","privacyQuestion":"Werden meine Werte hochgeladen?","privacyAnswer":"Nein. Die Berechnung läuft in diesem Browser; \nDie Werte werden nicht hochgeladen oder gespeichert.","fields":{"mode":"Berechnung","momentumMode":"Nur Gesamtimpuls","collisionMode":"Modellieren Sie eine Kollision","mass1":"Objekt 1 Masse","mass2":"Objekt 2 Masse","massUnit":"Masseneinheit","kilograms":"Kilogramm (kg)","grams":"Gramm (g)","tonnes":"Tonnen (t)","velocity1":"Anfangsgeschwindigkeit von Objekt 1","velocity2":"Objekt 2 Anfangsgeschwindigkeit","speedUnit":"Geschwindigkeitseinheit","metersPerSecond":"Meter pro Sekunde (m/s)","kilometersPerHour":"Kilometer pro Stunde (km/h)","feetPerSecond":"Fuß pro Sekunde (ft/s)","restitution":"Restitutionskoeffizient (0–1)","accuracyNote":"Eindimensionales klassisches Modell. \nPositive und negative Geschwindigkeiten geben die Richtung an. \nKollisionen werden als isoliert behandelt: Es werden keine externen Impulse, Rotationen, Verformungsdetails oder relativistischen Effekte modelliert. \nEin Wert von 1 ist ideal elastisch; \n0 ist vollkommen unelastisch. \nHierbei handelt es sich um eine pädagogische Schätzung, nicht um eine technische oder sicherheitstechnische Bewertung."},"actions":{"calculate":"Berechnen","reset":"Klar","copy":"Ergebnis kopieren","example":"Versuchen Sie, gleiche Massen zusammenzustoßen","result":"Momentum-Ergebnis"},"messages":{"calculated":"Berechnung bereit.","checkInputs":"Geben Sie zwei positive Massen, gültige Geschwindigkeiten mit Vorzeichen, unterstützte Einheiten und einen Rückgabewert von 0 bis 1 ein.","momentumBefore":"Gesamtimpuls vor der Kollision","kineticEnergyBefore":"Gesamte kinetische Energie vor der Kollision","finalVelocity1":"Objekt 1 Endgeschwindigkeit","finalVelocity2":"Objekt 2 Endgeschwindigkeit","momentumAfter":"Gesamtimpuls nach der Kollision","kineticEnergyAfter":"Gesamte kinetische Energie nach der Kollision","energyLoss":"Im Modell umgewandelte oder verlorene kinetische Energie"},"additionalFaqs":[{"question":"Was bedeutet eine negative Geschwindigkeit?","answer":"Dies bedeutet, dass sich das Objekt in die entgegengesetzte Richtung zu der von Ihnen gewählten positiven Richtung bewegt. \nBehalten Sie das Vorzeichen bei der Eingabe beider Geschwindigkeiten bei; \nes beeinflusst den Gesamtimpuls und das Kollisionsergebnis."},{"question":"Was bedeutet der Rückerstattungskoeffizient?","answer":"Sie beschreibt die relative Trenngeschwindigkeit nach einem eindimensionalen Aufprall im Vergleich zur Annäherungsgeschwindigkeit. \nZero modelliert eine vollkommen unelastische Kollision; \nman modelliert einen idealen elastischen Stoß. \nEchte Materialien können je nach Aufprallbedingungen variieren."},{"question":"Bleibt der Impuls bei jeder Kollision erhalten?","answer":"Der Gesamtimpuls bleibt in diesem Modell erhalten, wenn das Zwei-Objekt-System keinen externen Nettoimpuls hat. \nDer Rechner zeigt Werte vorher und nachher an, damit Sie sie vergleichen können."},{"question":"Deckt dieser Rechner Winkel- oder Rotationskollisionen ab?","answer":"Nein. Es modelliert die Bewegung nur auf einer geraden Linie. \nEs werden keine Winkel, Drehungen, Objektformen, Geräusche, Wärmedetails oder Verformungen berechnet."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ja":{"copyLanguage":"ja","name":"運動量計算機","title":"運動量計算機無料 | UsefulVerse","description":"1 次元の運動量を計算するか、符号付き速度で 2 つのオブジェクトの衝突をモデル化します。\n無料でローカル。","intro":"1 つの線に沿って移動する 2 つの物体の合計運動量を求めるか、衝突後の速度を推定します。\n各方向を正または負の速度で設定し、反発係数を 0 ～ 1 から選択します。","howQuestion":"運動量と衝突速度はどのように計算しますか?","howAnswer":"運動量は質量と速度の積、p = mv であり、合計は両方のオブジェクトの符号付き合計です。 \n1 次元衝突の場合、この計算機は反発係数を使用して各最終速度を推定します。\nたとえば、理想的な弾性衝突では、+2 m/s と -1 m/s で移動する等しい 1 kg の質量が速度を交換しますが、総運動量は 1 kg·m/s のままです。","privacyQuestion":"私の値はアップロードされていますか?","privacyAnswer":"いいえ。計算はこのブラウザで実行されます。\n値はアップロードまたは保存されません。","fields":{"mode":"計算","momentumMode":"総運動量のみ","collisionMode":"衝突のモデル化","mass1":"オブジェクト 1 質量","mass2":"オブジェクト 2 の質量","massUnit":"質量単位","kilograms":"キログラム (kg)","grams":"グラム (g)","tonnes":"トン (t)","velocity1":"オブジェクト 1 の初速度","velocity2":"オブジェクト 2 の初速度","speedUnit":"速度単位","metersPerSecond":"メートル/秒 (m/s)","kilometersPerHour":"キロメートル毎時 (km/h)","feetPerSecond":"フィート/秒 (ft/s)","restitution":"反発係数 (0–1)","accuracyNote":"1 次元の古典的なモデル。\n正と負の速度は方向を示します。\n衝突は孤立したものとして扱われます。外部衝撃、回転、変形の詳細、または相対論的効果はモデル化されません。\n値 1 は理想的な弾性です。 \n0 は完全に非弾性です。\nこれは教育上の推定であり、工学的または安全性の評価ではありません。"},"actions":{"calculate":"計算してください","reset":"クリア","copy":"コピー結果","example":"等しい質量の衝突を試してください","result":"勢いの結果"},"messages":{"calculated":"計算の準備ができました。","checkInputs":"2 つの正の質量、有効な符号付き速度、サポートされる単位、および 0 ～ 1 の復元値を入力します。","momentumBefore":"衝突前の総運動量","kineticEnergyBefore":"衝突前の総運動エネルギー","finalVelocity1":"オブジェクト 1 の最終速度","finalVelocity2":"オブジェクト 2 の最終速度","momentumAfter":"衝突後の総運動量","kineticEnergyAfter":"衝突後の総運動エネルギー","energyLoss":"モデル内で変換または損失した運動エネルギー"},"additionalFaqs":[{"question":"負の速度とは何を意味しますか?","answer":"これは、オブジェクトが選択した正の方向とは反対の方向に移動することを意味します。\n両方の速度を入力するときは、符号を維持してください。\nそれは総運動量と衝突結果に影響します。"},{"question":"反発係数とは何を意味しますか?","answer":"接近速度と比較した、一次元衝撃後の相対的な分離速度を示します。 \nZero は完全に非弾性衝突をモデル化します。 \n1 つは理想的な弾性衝突をモデル化したものです。\n実際の材質は衝撃条件によって異なる場合があります。"},{"question":"すべての衝突で運動量は保存されますか?","answer":"2 オブジェクト システムに正味の外部力積がない場合、このモデルでは総運動量が保存されます。\n計算機には前後の値が表示されるので、比較できます。"},{"question":"この計算機は斜め衝突や回転衝突をカバーしますか?","answer":"いいえ。1 つの直線上の動きのみをモデル化します。\n角度、回転、オブジェクトの形状、音、熱の詳細、変形は計算されません。"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ko":{"copyLanguage":"ko","name":"운동량 계산기","title":"운동량 계산기 무료 | UsefulVerse","description":"1차원 운동량을 계산하거나 부호 있는 속도로 두 객체 충돌을 모델링합니다. \n무료이며 지역적입니다.","intro":"한 선을 따라 움직이는 두 물체의 총 운동량을 구하거나 충돌 후 속도를 추정합니다. \n각 방향을 양수 또는 음수 속도로 설정하고 복원 계수를 0에서 1까지 선택합니다.","howQuestion":"운동량과 충돌 속도는 어떻게 계산하나요?","howAnswer":"운동량은 질량 곱하기 속도, p = mv이고 총계는 두 물체의 부호 있는 합입니다. \n1차원 충돌의 경우 이 계산기는 반발 계수를 사용하여 각 최종 속도를 추정합니다. \n예를 들어, 이상적인 탄성 충돌에서 +2m/s와 -1m/s로 움직이는 동일한 1kg 질량은 속도를 교환하며 총 운동량은 1kg·m/s로 유지됩니다.","privacyQuestion":"내 값이 업로드됩니까?","privacyAnswer":"아니요. 계산은 이 브라우저에서 실행됩니다. \n값은 업로드되거나 저장되지 않습니다.","fields":{"mode":"계산","momentumMode":"총 운동량만","collisionMode":"충돌 모델링","mass1":"개체 1 질량","mass2":"개체 2 질량","massUnit":"질량 단위","kilograms":"킬로그램(kg)","grams":"그램(g)","tonnes":"미터톤(t)","velocity1":"객체 1 초기 속도","velocity2":"객체 2 초기 속도","speedUnit":"속도 단위","metersPerSecond":"초당 미터(m/s)","kilometersPerHour":"시간당 킬로미터(km/h)","feetPerSecond":"초당 피트(ft/s)","restitution":"복원 계수(0–1)","accuracyNote":"1차원 클래식 모델. \n양의 속도와 음의 속도는 방향을 나타냅니다. \n충돌은 고립된 것으로 처리됩니다. 외부 충격, 회전, 변형 세부 사항 또는 상대론적 효과는 모델링되지 않습니다. \n값 1은 이상적인 탄력성을 나타냅니다. \n0은 완전 비탄력적이다. \n이는 공학적 평가나 안전성 평가가 아닌 교육적 평가입니다."},"actions":{"calculate":"계산하다","reset":"지우기","copy":"결과 복사","example":"동일한 질량 충돌을 시도해 보세요.","result":"모멘텀 결과"},"messages":{"calculated":"계산이 준비되었습니다.","checkInputs":"두 개의 양의 질량, 유효한 부호 있는 속도, 지원되는 단위 및 0에서 1 사이의 복원 값을 입력하십시오.","momentumBefore":"충돌 전 총 운동량","kineticEnergyBefore":"충돌 전 총 운동에너지","finalVelocity1":"객체 1 최종 속도","finalVelocity2":"객체 2 최종 속도","momentumAfter":"충돌 후 총 운동량","kineticEnergyAfter":"충돌 후 총 운동에너지","energyLoss":"모델에서 변환되거나 손실된 운동 에너지"},"additionalFaqs":[{"question":"음의 속도는 무엇을 의미하나요?","answer":"이는 개체가 선택한 양의 방향과 반대 방향으로 이동한다는 의미입니다. \n두 속도를 모두 입력할 때는 기호를 유지하십시오. \n이는 총 운동량과 충돌 결과에 영향을 미칩니다."},{"question":"복원계수는 무엇을 의미하나요?","answer":"접근 속도와 비교하여 1차원 충돌 후 상대적인 분리 속도를 설명합니다. \nZero는 완벽하게 비탄성인 충돌을 모델링합니다. \n하나는 이상적인 탄성 충돌을 모델링합니다. \n실제 재료는 충격 조건에 따라 달라질 수 있습니다."},{"question":"모든 충돌에서 운동량은 보존됩니까?","answer":"이 모델에서는 두 물체 시스템에 순 외부 자극이 없을 때 전체 운동량이 보존됩니다. \n계산기에는 전후의 값이 표시되므로 비교할 수 있습니다."},{"question":"이 계산기는 각도 충돌 또는 회전 충돌을 처리합니까?","answer":"아니요. 하나의 직선에서만 동작을 모델링합니다. \n각도, 회전, 물체 모양, 소리, 열 세부 사항 또는 변형을 계산하지 않습니다."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"id":{"copyLanguage":"id","name":"Kalkulator Momentum","title":"Kalkulator Momentum Gratis | UsefulVerse","description":"Hitung momentum satu dimensi atau modelkan tumbukan dua benda dengan kecepatan tertentu. \nGratis dan lokal.","intro":"Temukan momentum total dua benda yang bergerak sepanjang satu garis, atau perkirakan kecepatannya setelah tumbukan. \nTetapkan setiap arah dengan kecepatan positif atau negatif dan pilih koefisien restitusi dari 0 hingga 1.","howQuestion":"Bagaimana cara menghitung momentum dan kecepatan tumbukan?","howAnswer":"Momentum adalah massa dikalikan kecepatan, p = mv, dan jumlah total kedua benda. \nUntuk tumbukan satu dimensi, kalkulator ini menggunakan koefisien restitusi untuk memperkirakan setiap kecepatan akhir. \nMisalnya, massa bermassa sama dengan 1 kg bergerak dengan kecepatan +2 m/s dan −1 m/s dalam tumbukan lenting ideal, sedangkan momentum total tetap 1 kg·m/s.","privacyQuestion":"Apakah nilai saya sudah diunggah?","privacyAnswer":"No. Perhitungan berjalan di browser ini; \nnilainya tidak diunggah atau disimpan.","fields":{"mode":"Perhitungan","momentumMode":"Total momentum saja","collisionMode":"Modelkan tabrakan","mass1":"Benda 1 massa","mass2":"Massa benda 2","massUnit":"Satuan massa","kilograms":"Kilogram (kg)","grams":"Gram (g)","tonnes":"Metrik ton (t)","velocity1":"Kecepatan awal benda 1","velocity2":"Kecepatan awal benda 2","speedUnit":"Satuan kecepatan","metersPerSecond":"Meter per detik (m/s)","kilometersPerHour":"Kilometer per jam (km/jam)","feetPerSecond":"Kaki per detik (kaki/s)","restitution":"Koefisien restitusi (0–1)","accuracyNote":"Model klasik satu dimensi. \nKecepatan positif dan negatif menunjukkan arah. \nTabrakan diperlakukan sebagai tabrakan terisolasi: tidak ada impuls eksternal, rotasi, detail deformasi, atau efek relativistik yang dimodelkan. \nNilai 1 adalah elastis ideal; \n0 bersifat inelastis sempurna. \nIni adalah perkiraan pendidikan, bukan penilaian teknik atau keselamatan."},"actions":{"calculate":"Hitung","reset":"Bersih","copy":"Salin hasil","example":"Coba tumbukan bermassa sama besar","result":"Hasil momentum"},"messages":{"calculated":"Perhitungan siap.","checkInputs":"Masukkan dua massa positif, kecepatan bertanda tangan yang valid, satuan pendukung, dan nilai restitusi dari 0 hingga 1.","momentumBefore":"Momentum total sebelum tumbukan","kineticEnergyBefore":"Total energi kinetik sebelum tumbukan","finalVelocity1":"Kecepatan akhir benda 1","finalVelocity2":"Kecepatan akhir benda 2","momentumAfter":"Momentum total setelah tumbukan","kineticEnergyAfter":"Energi kinetik total setelah tumbukan","energyLoss":"Energi kinetik diubah atau hilang dalam model"},"additionalFaqs":[{"question":"Apa yang dimaksud dengan kecepatan negatif?","answer":"Artinya benda bergerak berlawanan arah dengan arah positif yang anda pilih. \nPertahankan tanda tersebut ketika memasuki kedua kecepatan; \nitu mempengaruhi momentum total dan hasil tumbukan."},{"question":"Apa yang dimaksud dengan koefisien restitusi?","answer":"Ini menggambarkan kecepatan pemisahan relatif setelah tumbukan satu dimensi dibandingkan dengan kecepatan mendekat. \nNol memodelkan tumbukan tidak lenting sempurna; \nsalah satu model tumbukan elastik ideal. \nBahan asli dapat bervariasi sesuai kondisi benturan."},{"question":"Apakah momentum kekal pada setiap tumbukan?","answer":"Momentum total kekal dalam model ini ketika sistem dua benda tidak mempunyai impuls eksternal netto. \nKalkulator menampilkan nilai sebelum dan sesudah sehingga Anda dapat membandingkannya."},{"question":"Apakah kalkulator ini mencakup tumbukan sudut atau tumbukan berputar?","answer":"Tidak. Ini memodelkan gerak pada satu garis lurus saja. \nItu tidak menghitung sudut, rotasi, bentuk objek, suara, detail panas, atau deformasi."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"hi":{"copyLanguage":"hi","name":"Momentum Calculator","title":"Momentum Calculator Free | UsefulVerse","description":"एक-आयामी गति की गणना करें या हस्ताक्षरित गति के साथ दो-वस्तु टकराव का मॉडल बनाएं। \nमुफ़्त और स्थानीय.","intro":"एक रेखा पर गतिमान दो वस्तुओं का कुल संवेग ज्ञात करें, या टक्कर के बाद उनकी गति का अनुमान लगाएं। \nप्रत्येक दिशा को सकारात्मक या नकारात्मक वेग के साथ सेट करें और 0 से 1 तक पुनर्स्थापन गुणांक चुनें।","howQuestion":"आप संवेग और टक्कर गति की गणना कैसे करते हैं?","howAnswer":"संवेग द्रव्यमान गुना वेग है, पी = एमवी, और कुल दोनों वस्तुओं के लिए हस्ताक्षरित योग है। \nएक-आयामी टक्कर के लिए, यह कैलकुलेटर प्रत्येक अंतिम वेग का अनुमान लगाने के लिए पुनर्स्थापन के गुणांक का उपयोग करता है। \nउदाहरण के लिए, एक आदर्श लोचदार टकराव में समान 1 किलो द्रव्यमान +2 मीटर/सेकंड और -1 मीटर/सेकेंड की विनिमय गति से चलते हैं, जबकि कुल गति 1 किलो·मीटर/सेकंड रहती है।","privacyQuestion":"क्या मेरे मान अपलोड किए गए हैं?","privacyAnswer":"नहीं। गणना इस ब्राउज़र में चलती है; \nमान अपलोड या सहेजे नहीं गए हैं.","fields":{"mode":"गणना","momentumMode":"केवल कुल गति","collisionMode":"मॉडल टकराव\n\n654321000111223456 वस्तु 1 द्रव्यमान","mass1":"Object 1 mass","mass2":"वस्तु 2 द्रव्यमान","massUnit":"द्रव्यमान इकाई","kilograms":"किलोग्राम (किग्रा)","grams":"ग्राम (ग्राम)","tonnes":"मीट्रिक टन (टी)","velocity1":"वस्तु 1 प्रारंभिक वेग","velocity2":"वस्तु 2 प्रारंभिक वेग","speedUnit":"वेग इकाई","metersPerSecond":"मीटर प्रति सेकंड (एम/एस)","kilometersPerHour":"किलोमीटर प्रति घंटा (किमी/घंटा)","feetPerSecond":"फीट प्रति सेकंड (फीट/सेकंड)","restitution":"क्षतिपूर्ति का गुणांक (0-1)","accuracyNote":"एक आयामी शास्त्रीय मॉडल। \nसकारात्मक और नकारात्मक वेग दिशा दिखाते हैं। \nटकरावों को अलग-थलग माना जाता है: कोई बाहरी आवेग, घूर्णन, विरूपण विवरण या सापेक्ष प्रभाव का मॉडल नहीं बनाया जाता है। \n1 का मान आदर्श लोचदार है; \n0 पूर्णतया बेलोचदार है। \nयह एक शैक्षिक अनुमान है, इंजीनियरिंग या सुरक्षा मूल्यांकन नहीं।"},"actions":{"calculate":"गणना करें","reset":"साफ़","copy":"परिणाम कॉपी करें","example":"समान द्रव्यमानों को टकराने का प्रयास करें","result":"गति परिणाम"},"messages":{"calculated":"गणना तैयार।","checkInputs":"दो सकारात्मक द्रव्यमान, वैध हस्ताक्षरित वेग, समर्थित इकाइयाँ और 0 से 1 तक एक पुनर्स्थापन मान दर्ज करें।","momentumBefore":"टक्कर से पहले कुल गति","kineticEnergyBefore":"टक्कर से पहले कुल गतिज ऊर्जा","finalVelocity1":"Object 1 final velocity","finalVelocity2":"वस्तु 2 अंतिम वेग","momentumAfter":"टक्कर के बाद कुल गति","kineticEnergyAfter":"टक्कर के बाद कुल गतिज ऊर्जा","energyLoss":"गतिज ऊर्जा मॉडल में परिवर्तित या नष्ट हो गई"},"additionalFaqs":[{"question":"ऋणात्मक वेग का क्या अर्थ है?","answer":"इसका मतलब है कि वस्तु आपके द्वारा चुनी गई सकारात्मक दिशा से विपरीत दिशा में चलती है। \nदोनों वेगों में प्रवेश करते समय चिन्ह रखें; \nयह कुल गति और टकराव के परिणाम को प्रभावित करता है।"},{"question":"पुनर्स्थापन गुणांक का क्या अर्थ है?","answer":"यह आने वाली गति की तुलना में एक-आयामी प्रभाव के बाद सापेक्ष पृथक्करण गति का वर्णन करता है। \nशून्य मॉडल पूरी तरह से बेलोचदार टक्कर है; \nएक आदर्श लोचदार टक्कर का मॉडल तैयार करता है। \nवास्तविक सामग्रियां प्रभाव की स्थितियों के साथ भिन्न हो सकती हैं।"},{"question":"क्या प्रत्येक टक्कर में संवेग संरक्षित रहता है?","answer":"इस मॉडल में कुल गति संरक्षित रहती है जब दो-ऑब्जेक्ट प्रणाली में कोई शुद्ध बाहरी आवेग नहीं होता है। \nकैलकुलेटर पहले और बाद के मान दिखाता है ताकि आप उनकी तुलना कर सकें।"},{"question":"क्या यह कैलकुलेटर कोणीय या घूर्णनशील टकरावों को कवर करता है?","answer":"नहीं। यह केवल एक सीधी रेखा पर गति दर्शाता है। \nयह कोण, घूर्णन, वस्तु आकार, ध्वनि, ताप विवरण या विरूपण की गणना नहीं करता है।"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ar":{"copyLanguage":"ar","name":"حاسبة الزخم والتصادم","title":"حاسبة الزخم والتصادم مجانًا | UsefulVerse","description":"احسب الزخم الكلي والسرعات بعد تصادم أحادي البعد. مجانًا وتُجرى الحسابات في متصفحك.","intro":"أوجد كمية الحركة الكلية لجسمين يتحركان على طول خط واحد، أو قدّر سرعتهما بعد الاصطدام. \nاضبط كل اتجاه بسرعة إيجابية أو سلبية واختر معامل الاسترداد من 0 إلى 1.","howQuestion":"كيف تحسب الزخم وسرعات الاصطدام؟","howAnswer":"الزخم هو الكتلة مضروبة في السرعة، p = mv، والإجمالي هو المجموع الموقع لكلا الجسمين. \nبالنسبة للتصادم أحادي البعد، تستخدم هذه الآلة الحاسبة معامل الاسترداد لتقدير كل سرعة نهائية. \nعلى سبيل المثال، تتحرك كتلتان متساويتان كتلتهما 1 كجم بسرعات متبادلة +2 م/ث و-1 م/ث في تصادم مرن مثالي، بينما يظل الزخم الإجمالي 1 كجم · م/ث.","privacyQuestion":"هل تم تحميل القيم الخاصة بي؟","privacyAnswer":"لا. يتم تشغيل الحساب في هذا المتصفح؛ \nلا يتم تحميل القيم أو حفظها.","fields":{"mode":"نوع الحساب","momentumMode":"الزخم الكلي فقط","collisionMode":"نمذجة تصادم","mass1":"كتلة الجسم الأول","mass2":"كتلة الجسم الثاني","massUnit":"وحدة الكتلة","kilograms":"كيلوغرام (kg)","grams":"غرام (g)","tonnes":"طن متري (t)","velocity1":"السرعة الابتدائية للجسم الأول","velocity2":"السرعة الابتدائية للجسم الثاني","speedUnit":"وحدة السرعة","metersPerSecond":"متر في الثانية (m/s)","kilometersPerHour":"كيلومتر في الساعة (km/h)","feetPerSecond":"قدم في الثانية (ft/s)","restitution":"معامل الارتداد (من 0 إلى 1)","accuracyNote":"نموذج كلاسيكي أحادي البعد. \nالسرعات الإيجابية والسلبية تظهر الاتجاه. \nيتم التعامل مع التصادمات على أنها معزولة: لا يتم تصميم أي دافع خارجي أو دوران أو تفاصيل تشوه أو تأثيرات نسبية. \nالقيمة 1 هي المرونة المثالية؛ \n0 غير مرن تمامًا. \nهذا تقدير تعليمي، وليس تقييمًا هندسيًا أو تقييمًا للسلامة."},"actions":{"calculate":"احسب","reset":"مسح","copy":"نسخ النتيجة","example":"حاول تصادم الكتل المتساوية","result":"نتيجة الزخم"},"messages":{"calculated":"الحساب جاهز.","checkInputs":"أدخل كتلتين موجبتين، والسرعات الموقعة الصحيحة، والوحدات المدعومة، وقيمة الاسترداد من 0 إلى 1.","momentumBefore":"الزخم الكلي قبل التصادم","kineticEnergyBefore":"الطاقة الحركية الكلية قبل التصادم","finalVelocity1":"السرعة النهائية للجسم الأول","finalVelocity2":"السرعة النهائية للجسم الثاني","momentumAfter":"الزخم الكلي بعد التصادم","kineticEnergyAfter":"الطاقة الحركية الكلية بعد التصادم","energyLoss":"الطاقة الحركية المحولة أو المفقودة في النموذج"},"additionalFaqs":[{"question":"ماذا تعني السرعة السلبية؟","answer":"يعني أن الجسم يتحرك في الاتجاه المعاكس للاتجاه الموجب الذي اخترته. \nاحتفظ بالعلامة عند دخول السرعتين؛ \nفإنه يؤثر على الزخم الكلي ونتيجة الاصطدام."},{"question":"ماذا يعني معامل الرد؟","answer":"يصف سرعة الفصل النسبية بعد تأثير أحادي البعد مقارنة بسرعة الاقتراب. \nنماذج الصفر تصادم غير مرن تمامًا؛ \nأحد نماذج الاصطدام المرن المثالي. \nيمكن أن تختلف المواد الحقيقية باختلاف ظروف التأثير."},{"question":"هل يتم حفظ الزخم في كل تصادم؟","answer":"يتم الحفاظ على الزخم الإجمالي في هذا النموذج عندما لا يكون للنظام المكون من كائنين أي دافع خارجي صافي. \nتعرض الآلة الحاسبة القيم قبل وبعد حتى تتمكن من مقارنتها."},{"question":"هل تغطي هذه الآلة الحاسبة التصادمات الزاوية أو الدوارة؟","answer":"لا. إنها تمثل الحركة على خط مستقيم واحد فقط. \nلا يحسب الزوايا أو الدوران أو شكل الجسم أو الصوت أو تفاصيل الحرارة أو التشوه."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"zh":{"copyLanguage":"zh","name":"动量计算器","title":"动量计算器免费 | UsefulVerse","description":"计算一维动量或对具有符号速度的两个物体碰撞进行建模。\n免费且本地化。","intro":"求两个沿一条直线移动的物体的总动量，或估计它们在碰撞后的速度。\n将每个方向设置为正速度或负速度，并选择 0 到 1 之间的恢复系数。","howQuestion":"如何计算动量和碰撞速度？","howAnswer":"动量是质量乘以速度，p = mv，总和是两个对象的有符号和。\n对于一维碰撞，该计算器使用恢复系数来估计每个最终速度。\n例如，在理想弹性碰撞中，以 +2 m/s 和 -1 m/s 移动的相同 1 kg 质量交换速度，而总动量仍为 1 kg·m/s。","privacyQuestion":"我的值是否已上传？","privacyAnswer":"否。计算在此浏览器中运行；\n这些值不会上传或保存。","fields":{"mode":"计算","momentumMode":"仅总动量","collisionMode":"模拟碰撞","mass1":"物体 1 质量","mass2":"物体 2 质量","massUnit":"质量单位","kilograms":"公斤 (kg)","grams":"克 (g)","tonnes":"公吨 (t)","velocity1":"对象 1 初始速度","velocity2":"物体 2 初始速度","speedUnit":"速度单位","metersPerSecond":"米每秒 (m/s)","kilometersPerHour":"公里每小时 (km/h)","feetPerSecond":"英尺每秒 (ft/s)","restitution":"恢复系数 (0–1)","accuracyNote":"一维经典模型。\n正速度和负速度显示方向。\n碰撞被视为孤立的：没有对外部脉冲、旋转、变形细节或相对论效应进行建模。\n值为 1 为理想弹性； \n0 是完全无弹性的。\n这是教育评估，而不是工程或安全评估。"},"actions":{"calculate":"计算","reset":"清除","copy":"复制结果","example":"尝试等质量碰撞","result":"动量结果"},"messages":{"calculated":"计算就绪。","checkInputs":"输入两个正质量、有效的带符号速度、支持的单位以及 0 到 1 之间的恢复值。","momentumBefore":"碰撞前总动量","kineticEnergyBefore":"碰撞前总动能","finalVelocity1":"对象 1 最终速度","finalVelocity2":"对象 2 最终速度","momentumAfter":"碰撞后总动量","kineticEnergyAfter":"碰撞后总动能","energyLoss":"模型中转换或损失的动能"},"additionalFaqs":[{"question":"负速度是什么意思？","answer":"表示物体向与您选择的正方向相反的方向移动。\n输入两个速度时保留符号；\n它影响总动量和碰撞结果。"},{"question":"恢复系数是什么意思？","answer":"描述一维撞击后与接近速度相比的相对分离速度。\n零模型完全非弹性碰撞；\n一种模型是理想的弹性碰撞。\n真实材料可能会因冲击条件而异。"},{"question":"每次碰撞时动量守恒吗？","answer":"当双物体系统没有净外部冲量时，该模型中的总动量守恒。\n计算器会显示之前和之后的值，以便您可以比较它们。"},{"question":"此计算器是否涵盖倾斜或旋转碰撞？","answer":"否。它仅模拟一条直线上的运动。\n它不计算角度、旋转、物体形状、声音、热量细节或变形。"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"bn":{"copyLanguage":"bn","name":"মোমেন্টাম ক্যালকুলেটর","title":"মোমেন্টাম ক্যালকুলেটর বিনামূল্যে | UsefulVerse","description":"এক-মাত্রিক ভরবেগ গণনা করুন বা স্বাক্ষরিত গতির সাথে একটি দ্বি-বস্তুর সংঘর্ষের মডেল করুন। \nবিনামূল্যে এবং স্থানীয়।","intro":"একটি লাইন বরাবর চলমান দুটি বস্তুর জন্য মোট গতিবেগ খুঁজুন, অথবা সংঘর্ষের পর তাদের গতি অনুমান করুন। \nপ্রতিটি দিক একটি ইতিবাচক বা ঋণাত্মক বেগের সাথে সেট করুন এবং 0 থেকে 1 পর্যন্ত পুনরুদ্ধারের সহগ বেছে নিন।","howQuestion":"আপনি কিভাবে ভরবেগ এবং সংঘর্ষের গতি গণনা করবেন?","howAnswer":"মোমেন্টাম হল ভর গুণের বেগ, p = mv, এবং মোট উভয় বস্তুর জন্য স্বাক্ষরিত যোগফল। \nএকটি এক-মাত্রিক সংঘর্ষের জন্য, এই ক্যালকুলেটর প্রতিটি চূড়ান্ত বেগ অনুমান করার জন্য পুনরুদ্ধারের সহগ ব্যবহার করে। \nউদাহরণস্বরূপ, একটি আদর্শ স্থিতিস্থাপক সংঘর্ষে সমান 1 kg ভর +2 m/s এবং −1 m/s বিনিময় গতিতে চলে, যখন মোট ভরবেগ 1 kg·m/s থেকে যায়।","privacyQuestion":"আমার মান কি আপলোড করা হয়েছে?","privacyAnswer":"নং। গণনা এই ব্রাউজারে চলে; \nমান আপলোড বা সংরক্ষণ করা হয় না.","fields":{"mode":"গণনা","momentumMode":"মোট ভরবেগ শুধুমাত্র","collisionMode":"মডেল একটি সংঘর্ষ","mass1":"বস্তু 1 ভর","mass2":"বস্তু 2 ভর","massUnit":"গণ ইউনিট","kilograms":"কিলোগ্রাম (কেজি)","grams":"গ্রাম (ছ)","tonnes":"মেট্রিক টন (টি)","velocity1":"অবজেক্ট 1 প্রাথমিক বেগ","velocity2":"অবজেক্ট 2 প্রাথমিক বেগ","speedUnit":"বেগ ইউনিট","metersPerSecond":"মিটার প্রতি সেকেন্ড (মি/সেকেন্ড)","kilometersPerHour":"কিলোমিটার প্রতি ঘন্টা (কিমি/ঘণ্টা)","feetPerSecond":"ফুট প্রতি সেকেন্ড (ফুট/সেকেন্ড)","restitution":"পুনরুদ্ধারের সহগ (0-1)","accuracyNote":"এক-মাত্রিক শাস্ত্রীয় মডেল। \nইতিবাচক এবং নেতিবাচক বেগ দিক নির্দেশ করে। \nসংঘর্ষগুলিকে বিচ্ছিন্ন হিসাবে বিবেচনা করা হয়: কোনও বাহ্যিক আবেগ, ঘূর্ণন, বিকৃতির বিবরণ বা আপেক্ষিক প্রভাবগুলি মডেল করা হয় না। \n1 এর মান আদর্শ ইলাস্টিক; \n0 পুরোপুরি স্থিতিস্থাপক। \nএটি একটি শিক্ষাগত অনুমান, প্রকৌশল বা নিরাপত্তা মূল্যায়ন নয়।"},"actions":{"calculate":"গণনা করুন","reset":"সাফ","copy":"ফলাফল কপি করুন","example":"সমান ভরের সংঘর্ষের চেষ্টা করুন","result":"মোমেন্টাম ফলাফল"},"messages":{"calculated":"গণনা প্রস্তুত।","checkInputs":"দুটি ধনাত্মক ভর, বৈধ স্বাক্ষরিত বেগ, সমর্থিত একক এবং 0 থেকে 1 পর্যন্ত একটি পুনরুদ্ধার মান লিখুন।","momentumBefore":"সংঘর্ষের আগে মোট গতিবেগ","kineticEnergyBefore":"সংঘর্ষের আগে মোট গতিশক্তি","finalVelocity1":"অবজেক্ট 1 চূড়ান্ত বেগ","finalVelocity2":"অবজেক্ট 2 চূড়ান্ত বেগ","momentumAfter":"সংঘর্ষের পর মোট গতিবেগ","kineticEnergyAfter":"সংঘর্ষের পর মোট গতিশক্তি","energyLoss":"গতিশক্তি মডেলে রূপান্তরিত বা হারিয়ে গেছে"},"additionalFaqs":[{"question":"ঋণাত্মক বেগ বলতে কী বোঝায়?","answer":"এর অর্থ হল বস্তুটি আপনার বেছে নেওয়া ইতিবাচক দিক থেকে বিপরীত দিকে চলে। \nউভয় বেগ প্রবেশ করার সময় চিহ্নটি রাখুন; \nএটি মোট ভরবেগ এবং সংঘর্ষের ফলাফলকে প্রভাবিত করে।"},{"question":"পুনরুদ্ধারের সহগ বলতে কী বোঝায়?","answer":"এটি কাছাকাছি গতির সাথে তুলনা করে এক-মাত্রিক প্রভাবের পরে আপেক্ষিক বিভাজক গতিকে বর্ণনা করে। \nজিরো মডেল একটি পুরোপুরি অস্থিতিশীল সংঘর্ষ; \nএকটি মডেল একটি আদর্শ ইলাস্টিক সংঘর্ষ. \nবাস্তব উপকরণ প্রভাব অবস্থার সঙ্গে পরিবর্তিত হতে পারে."},{"question":"প্রতি সংঘর্ষে কি ভরবেগ সংরক্ষিত হয়?","answer":"এই মডেলে মোট ভরবেগ সংরক্ষিত হয় যখন দুই-অবজেক্ট সিস্টেমের কোনো নেট এক্সটার্নাল ইম্পালস থাকে না। \nক্যালকুলেটর আগে এবং পরে মান দেখায় যাতে আপনি তাদের তুলনা করতে পারেন।"},{"question":"এই ক্যালকুলেটর কি কৌণিক বা ঘূর্ণায়মান সংঘর্ষকে কভার করে?","answer":"নং। এটি শুধুমাত্র একটি সরল রেখায় গতির মডেল করে। \nএটি কোণ, ঘূর্ণন, বস্তুর আকৃতি, শব্দ, তাপের বিবরণ বা বিকৃতি গণনা করে না।"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ru":{"copyLanguage":"ru","name":"Калькулятор импульса","title":"Калькулятор импульса Бесплатно | UsefulVerse","description":"Рассчитайте одномерный импульс или смоделируйте столкновение двух объектов со знаковыми скоростями. \nБесплатно и локально.","intro":"Найдите суммарный импульс двух объектов, движущихся по одной прямой, или оцените их скорости после столкновения. \nУстановите для каждого направления положительную или отрицательную скорость и выберите коэффициент восстановления от 0 до 1.","howQuestion":"Как рассчитать импульс и скорость столкновения?","howAnswer":"Импульс — это масса, умноженная на скорость, p = mv, а сумма — это сумма со знаком для обоих объектов. \nДля одномерного столкновения этот калькулятор использует коэффициент восстановления для оценки каждой конечной скорости. \nНапример, равные массы массой 1 кг, движущиеся со скоростями +2 м/с и -1 м/с, обмениваются скоростями при идеальном упругом столкновении, в то время как общий импульс остается 1 кг·м/с.","privacyQuestion":"Мои значения загружены?","privacyAnswer":"Нет. Расчет выполняется в этом браузере; \nзначения не загружаются и не сохраняются.","fields":{"mode":"Расчет","momentumMode":"Только общий импульс","collisionMode":"Смоделировать столкновение.","mass1":"Масса объекта 1","mass2":"Масса объекта 2","massUnit":"Единица массы","kilograms":"Килограммы (кг)","grams":"Грамм (г)","tonnes":"Метрические тонны (т)","velocity1":"Начальная скорость объекта 1","velocity2":"Начальная скорость объекта 2","speedUnit":"Блок скорости","metersPerSecond":"Метров в секунду (м/с)","kilometersPerHour":"Километров в час (км/ч)","feetPerSecond":"Футов в секунду (фут/с)","restitution":"Коэффициент реституции (0–1)","accuracyNote":"Одномерная классическая модель. \nПоложительные и отрицательные скорости показывают направление. \nСтолкновения рассматриваются как изолированные: внешний импульс, вращение, детали деформации или релятивистские эффекты не моделируются. \nЗначение 1 соответствует идеальной эластичности; \n0 совершенно неэластичен. \nЭто образовательная оценка, а не инженерная оценка или оценка безопасности."},"actions":{"calculate":"Рассчитать","reset":"Прозрачный","copy":"Копировать результат","example":"Попробуй столкнуться равными массами.","result":"Результат импульса"},"messages":{"calculated":"Расчет готов.","checkInputs":"Введите две положительные массы, действительные скорости со знаком, поддерживаемые единицы измерения и значение восстановления от 0 до 1.","momentumBefore":"Суммарный импульс до столкновения","kineticEnergyBefore":"Полная кинетическая энергия до столкновения","finalVelocity1":"Конечная скорость объекта 1","finalVelocity2":"Конечная скорость объекта 2","momentumAfter":"Суммарный импульс после столкновения","kineticEnergyAfter":"Полная кинетическая энергия после столкновения","energyLoss":"Кинетическая энергия, преобразованная или потерянная в модели."},"additionalFaqs":[{"question":"Что означает отрицательная скорость?","answer":"Это означает, что объект движется в направлении, противоположном выбранному вами положительному направлению. \nДержите знак при вводе обеих скоростей; \nэто влияет на общий импульс и результат столкновения."},{"question":"Что означает коэффициент реституции?","answer":"Описывает относительную скорость отделения после одномерного удара по сравнению со скоростью приближения. \nЗеро моделирует совершенно неупругое столкновение; \nмоделируется идеальное упругое столкновение. \nРеальные материалы могут различаться в зависимости от условий воздействия."},{"question":"Сохраняется ли количество движения при каждом столкновении?","answer":"Полный импульс сохраняется в этой модели, когда система двух объектов не имеет чистого внешнего импульса. \nКалькулятор показывает значения до и после, чтобы вы могли их сравнить."},{"question":"Этот калькулятор учитывает столкновения под углом или при вращении?","answer":"Нет. Он моделирует движение только по одной прямой. \nОн не рассчитывает углы, вращение, форму объекта, звук, тепловые детали или деформацию."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ur":{"copyLanguage":"ur","name":"مومنٹم کیلکولیٹر","title":"مومینٹم کیلکولیٹر مفت | UsefulVerse","description":"ایک جہتی رفتار کا حساب لگائیں یا دستخط شدہ رفتار کے ساتھ دو آبجیکٹ کے تصادم کا نمونہ بنائیں۔ \nمفت اور مقامی۔","intro":"ایک لائن کے ساتھ حرکت کرنے والی دو اشیاء کے لیے کل مومینٹم معلوم کریں، یا ٹکرانے کے بعد ان کی رفتار کا اندازہ لگائیں۔ \nہر سمت کو مثبت یا منفی رفتار کے ساتھ متعین کریں اور 0 سے 1 تک ریسٹیٹوشن کا گتانک منتخب کریں۔","howQuestion":"آپ رفتار اور تصادم کی رفتار کا حساب کیسے لگاتے ہیں؟","howAnswer":"مومینٹم ماس اوقات کی رفتار ہے، p = mv، اور کل دونوں اشیاء کے لیے دستخط شدہ رقم ہے۔ \nایک جہتی تصادم کے لیے، یہ کیلکولیٹر ہر آخری رفتار کا تخمینہ لگانے کے لیے معاوضے کے گتانک کا استعمال کرتا ہے۔ \nمثال کے طور پر، ایک مثالی لچکدار تصادم میں +2 m/s اور −1 m/s کے تبادلے کی رفتار سے 1 کلو گرام کے مساوی ماس حرکت کرتے ہیں، جبکہ کل رفتار 1 kg·m/s رہتی ہے۔","privacyQuestion":"کیا میری اقدار اپ لوڈ ہیں؟","privacyAnswer":"نمبر۔ حساب اس براؤزر میں چلتا ہے۔ \nاقدار اپ لوڈ یا محفوظ نہیں ہیں۔","fields":{"mode":"حساب","momentumMode":"صرف کل رفتار","collisionMode":"ماڈل ٹکراؤ","mass1":"آبجیکٹ 1 ماس","mass2":"آبجیکٹ 2 ماس","massUnit":"ماس یونٹ","kilograms":"کلوگرام (کلوگرام)","grams":"گرام (g)","tonnes":"میٹرک ٹن (ٹی)","velocity1":"آبجیکٹ 1 ابتدائی رفتار","velocity2":"آبجیکٹ 2 ابتدائی رفتار","speedUnit":"رفتار یونٹ","metersPerSecond":"میٹر فی سیکنڈ (m/s)","kilometersPerHour":"کلومیٹر فی گھنٹہ (کلومیٹر فی گھنٹہ)","feetPerSecond":"فٹ فی سیکنڈ (فٹ فی سیکنڈ)","restitution":"معاوضہ کا گتانک (0–1)","accuracyNote":"ایک جہتی کلاسیکی ماڈل۔ \nمثبت اور منفی رفتار سمت دکھاتی ہیں۔ \nتصادم کو الگ تھلگ سمجھا جاتا ہے: کوئی بیرونی تحریک، گردش، اخترتی کی تفصیل یا رشتہ دار اثرات کو ماڈل نہیں کیا جاتا ہے۔ \n1 کی قدر مثالی لچکدار ہے۔ \n0 بالکل غیر لچکدار ہے۔ \nیہ ایک تعلیمی تخمینہ ہے، انجینئرنگ یا حفاظت کا اندازہ نہیں۔"},"actions":{"calculate":"حساب لگائیں۔","reset":"صاف کریں۔","copy":"نتیجہ کاپی کریں۔","example":"مساوی بڑے پیمانے پر ٹکرانے کی کوشش کریں۔","result":"مومینٹم نتیجہ"},"messages":{"calculated":"حساب تیار ہے۔","checkInputs":"دو مثبت ماسز، درست دستخط شدہ رفتار، معاون یونٹس، اور 0 سے 1 تک کی واپسی کی قدر درج کریں۔","momentumBefore":"ٹکرانے سے پہلے کل مومنٹم","kineticEnergyBefore":"ٹکرانے سے پہلے کل حرکی توانائی","finalVelocity1":"آبجیکٹ 1 حتمی رفتار","finalVelocity2":"آبجیکٹ 2 حتمی رفتار","momentumAfter":"ٹکرانے کے بعد کل رفتار","kineticEnergyAfter":"ٹکرانے کے بعد کل حرکی توانائی","energyLoss":"ماڈل میں متحرک توانائی تبدیل یا ضائع"},"additionalFaqs":[{"question":"منفی رفتار کا کیا مطلب ہے؟","answer":"اس کا مطلب ہے کہ اعتراض آپ کے منتخب کردہ مثبت سمت سے مخالف سمت میں حرکت کرتا ہے۔ \nدونوں رفتار میں داخل ہوتے وقت نشان رکھیں۔ \nیہ کل رفتار اور تصادم کے نتیجے کو متاثر کرتا ہے۔"},{"question":"ریسٹی ٹیوشن کا کیا مطلب ہے؟","answer":"یہ قریب آنے والی رفتار کے مقابلے میں ایک جہتی اثر کے بعد رشتہ دار الگ ہونے والی رفتار کو بیان کرتا ہے۔ \nزیرو ماڈل ایک بالکل غیر لچکدار تصادم؛ \nایک ماڈل ایک مثالی لچکدار تصادم۔ \nحقیقی مواد اثر کے حالات کے ساتھ مختلف ہو سکتے ہیں۔"},{"question":"کیا ہر تصادم میں رفتار محفوظ ہے؟","answer":"اس ماڈل میں کل مومینٹم محفوظ رہتا ہے جب دو آبجیکٹ سسٹم میں کوئی خالص بیرونی تحریک نہ ہو۔ \nکیلکولیٹر پہلے اور بعد میں اقدار دکھاتا ہے تاکہ آپ ان کا موازنہ کر سکیں۔"},{"question":"کیا یہ کیلکولیٹر زاویہ یا گھومنے والی ٹکراؤ کا احاطہ کرتا ہے؟","answer":"نمبر۔ یہ حرکت کو صرف ایک سیدھی لائن پر ماڈل کرتا ہے۔ \nیہ زاویوں، گردش، آبجیکٹ کی شکل، آواز، حرارت کی تفصیلات یا اخترتی کا حساب نہیں لگاتا ہے۔"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"tr":{"copyLanguage":"tr","name":"Momentum Hesaplayıcı","title":"Momentum Hesaplayıcı Ücretsiz | UsefulVerse","description":"Tek boyutlu momentumu hesaplayın veya iki nesnenin çarpışmasını işaretli hızlarla modelleyin. \nÜcretsiz ve yerel.","intro":"Bir çizgi boyunca hareket eden iki nesnenin toplam momentumunu bulun veya çarpışma sonrasında hızlarını tahmin edin. \nHer yönü pozitif veya negatif bir hızla ayarlayın ve 0'dan 1'e kadar bir geri dönüş katsayısı seçin.","howQuestion":"Momentum ve çarpışma hızlarını nasıl hesaplarsınız?","howAnswer":"Momentum kütle çarpı hızdır, p = mv ve toplam her iki nesnenin işaretli toplamıdır. \nTek boyutlu bir çarpışma için bu hesaplayıcı, her bir son hızı tahmin etmek için eski haline dönme katsayısını kullanır. \nÖrneğin, ideal elastik çarpışmada +2 m/s ve -1 m/s değişim hızlarında hareket eden eşit 1 kg'lık kütleler varken toplam momentum 1 kg·m/s kalır.","privacyQuestion":"Değerlerim yüklendi mi?","privacyAnswer":"Hayır. Hesaplama bu tarayıcıda çalışır; \ndeğerler yüklenmez veya kaydedilmez.","fields":{"mode":"Hesaplama","momentumMode":"Yalnızca toplam momentum","collisionMode":"Çarpışmayı modelleyin","mass1":"Nesne 1 kütlesi","mass2":"Nesne 2 kütlesi","massUnit":"Kütle birimi","kilograms":"Kilogram (kg)","grams":"Gram (g)","tonnes":"Metrik ton (t)","velocity1":"Nesne 1 başlangıç hızı","velocity2":"Nesne 2 başlangıç hızı","speedUnit":"Hız birimi","metersPerSecond":"Saniyede metre (m/s)","kilometersPerHour":"Saatte kilometre (km/saat)","feetPerSecond":"Saniyede fit (ft/s)","restitution":"İade katsayısı (0–1)","accuracyNote":"Tek boyutlu klasik model. \nPozitif ve negatif hızlar yön gösterir. \nÇarpışmalar izole edilmiş gibi ele alınır: hiçbir dış etki, dönme, deformasyon detayı veya göreceli etkiler modellenmez. \n1 değeri ideal elastiktir; \n0 tamamen esnek değildir. \nBu bir mühendislik veya güvenlik değerlendirmesi değil, eğitim amaçlı bir tahmindir."},"actions":{"calculate":"Hesapla","reset":"Temizle","copy":"Sonucu kopyala","example":"Eşit kütlelerin çarpışmasını deneyin","result":"İvme sonucu"},"messages":{"calculated":"Hesaplama hazır.","checkInputs":"İki pozitif kütle, geçerli işaretli hızlar, desteklenen birimler ve 0 ile 1 arasında bir düzeltme değeri girin.","momentumBefore":"Çarpışmadan önceki toplam momentum","kineticEnergyBefore":"Çarpışmadan önceki toplam kinetik enerji","finalVelocity1":"Nesne 1'in son hızı","finalVelocity2":"Nesne 2'nin son hızı","momentumAfter":"Çarpışma sonrası toplam momentum","kineticEnergyAfter":"Çarpışma sonrası toplam kinetik enerji","energyLoss":"Modelde dönüştürülen veya kaybedilen kinetik enerji"},"additionalFaqs":[{"question":"Negatif hız ne anlama geliyor?","answer":"Nesnenin seçtiğiniz pozitif yönün tersi yönde hareket ettiği anlamına gelir. \nHer iki hızı da girerken işareti koruyun; \ntoplam momentumu ve çarpışma sonucunu etkiler."},{"question":"İade katsayısı ne anlama geliyor?","answer":"Yaklaşma hızıyla karşılaştırıldığında tek boyutlu bir çarpışma sonrasında bağıl ayrılma hızını tanımlar. \nSıfır, tamamen esnek olmayan bir çarpışmayı modeller; \nBunlardan biri ideal elastik çarpışmayı modelliyor. \nGerçek malzemeler darbe koşullarına göre değişiklik gösterebilir."},{"question":"Her çarpışmada momentum korunur mu?","answer":"İki nesneli sistemin net bir dış itici gücü olmadığında bu modelde toplam momentum korunur. \nHesap makinesi, karşılaştırma yapabilmeniz için önceki ve sonraki değerleri gösterir."},{"question":"Bu hesaplayıcı açılı veya dönen çarpışmaları kapsıyor mu?","answer":"Hayır. Hareketi yalnızca tek bir düz çizgi üzerinde modeller. \nAçıları, dönüşü, nesne şeklini, sesi, ısı ayrıntılarını veya deformasyonu hesaplamaz."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"vi":{"copyLanguage":"vi","name":"Máy tính động lượng","title":"Máy tính động lượng miễn phí | UsefulVerse","description":"Tính động lượng một chiều hoặc lập mô hình va chạm hai vật với tốc độ có dấu. \nMiễn phí và địa phương.","intro":"Tìm tổng động lượng của hai vật chuyển động dọc theo một đường thẳng hoặc ước tính tốc độ của chúng sau va chạm. \nĐặt mỗi hướng với vận tốc dương hoặc âm và chọn hệ số phục hồi từ 0 đến 1.","howQuestion":"Làm cách nào để tính động lượng và tốc độ va chạm?","howAnswer":"Động lượng là khối lượng nhân với vận tốc, p = mv, và tổng là tổng có dấu của cả hai vật. \nĐối với va chạm một chiều, máy tính này sử dụng hệ số phục hồi để ước tính từng vận tốc cuối cùng. \nVí dụ, các khối lượng bằng nhau 1 kg chuyển động với tốc độ +2 m/s và −1 m/s trong một va chạm đàn hồi lý tưởng, trong khi tổng động lượng vẫn là 1 kg·m/s.","privacyQuestion":"Giá trị của tôi có được tải lên không?","privacyAnswer":"Không. Phép tính chạy trong trình duyệt này; \ncác giá trị không được tải lên hoặc lưu.","fields":{"mode":"Tính toán","momentumMode":"Chỉ tổng động lượng","collisionMode":"Mô hình một vụ va chạm","mass1":"Khối lượng vật 1","mass2":"Khối lượng của vật thể 2","massUnit":"Đơn vị khối lượng","kilograms":"Kilôgam (kg)","grams":"Gam (g)","tonnes":"Tấn (t)","velocity1":"Vận tốc ban đầu của vật 1","velocity2":"Vận tốc ban đầu của vật 2","speedUnit":"Đơn vị vận tốc","metersPerSecond":"Mét trên giây (m/s)","kilometersPerHour":"Kilômét trên giờ (km/h)","feetPerSecond":"Feet trên giây (ft/s)","restitution":"Hệ số hoàn nguyên (0–1)","accuracyNote":"Mô hình cổ điển một chiều. \nVận tốc dương và âm cho biết hướng. \nCác va chạm được coi là cô lập: không có xung lực bên ngoài, chuyển động quay, chi tiết biến dạng hoặc hiệu ứng tương đối tính nào được mô hình hóa. \nGiá trị 1 là độ đàn hồi lý tưởng; \n0 hoàn toàn không co giãn. \nĐây là ước tính mang tính giáo dục, không phải đánh giá về mặt kỹ thuật hoặc an toàn."},"actions":{"calculate":"Tính toán","reset":"Xóa","copy":"Sao chép kết quả","example":"Thử va chạm khối lượng bằng nhau","result":"Kết quả động lượng"},"messages":{"calculated":"Tính toán đã sẵn sàng.","checkInputs":"Nhập hai khối lượng dương, vận tốc có dấu hợp lệ, đơn vị được hỗ trợ và giá trị hoàn lại từ 0 đến 1.","momentumBefore":"Tổng động lượng trước va chạm","kineticEnergyBefore":"Tổng động năng trước va chạm","finalVelocity1":"Vận tốc cuối cùng của vật thể 1","finalVelocity2":"Vận tốc cuối cùng của vật thể 2","momentumAfter":"Tổng động lượng sau va chạm","kineticEnergyAfter":"Tổng động năng sau va chạm","energyLoss":"Động năng được chuyển đổi hoặc mất đi trong mô hình"},"additionalFaqs":[{"question":"Vận tốc âm có nghĩa là gì?","answer":"Nó có nghĩa là vật chuyển động theo hướng ngược lại với hướng dương mà bạn đã chọn. \nGiữ nguyên dấu khi nhập cả hai vận tốc; \nnó ảnh hưởng đến tổng động lượng và kết quả va chạm."},{"question":"Hệ số hoàn nguyên có ý nghĩa gì?","answer":"Nó mô tả tốc độ tách tương đối sau va chạm một chiều so với tốc độ tiếp cận. \nZero mô hình hóa một va chạm hoàn toàn không đàn hồi; \nngười ta mô hình hóa một va chạm đàn hồi lý tưởng. \nVật liệu thật có thể thay đổi tùy theo điều kiện va đập."},{"question":"Động lượng có được bảo toàn trong mọi va chạm không?","answer":"Tổng động lượng được bảo toàn trong mô hình này khi hệ hai vật không có tổng xung lực bên ngoài. \nMáy tính hiển thị các giá trị trước và sau để bạn có thể so sánh chúng."},{"question":"Máy tính này có bao gồm các va chạm góc cạnh hoặc xoay không?","answer":"Không. Nó chỉ mô phỏng chuyển động trên một đường thẳng. \nNó không tính toán góc, góc quay, hình dạng vật thể, âm thanh, chi tiết nhiệt hay biến dạng."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"it":{"copyLanguage":"it","name":"Calcolatore della quantità di moto","title":"Calcolatore del momento gratuito | UsefulVerse","description":"Calcola la quantità di moto unidimensionale o modella una collisione di due oggetti con velocità con segno. \nGratuito e locale.","intro":"Trova la quantità di moto totale di due oggetti che si muovono lungo una linea o stima la loro velocità dopo una collisione. \nImposta ciascuna direzione con una velocità positiva o negativa e scegli un coefficiente di restituzione da 0 a 1.","howQuestion":"Come si calcola la quantità di moto e la velocità di collisione?","howAnswer":"La quantità di moto è la massa per la velocità, p = mv, e il totale è la somma con segno per entrambi gli oggetti. \nPer una collisione unidimensionale, questo calcolatore utilizza il coefficiente di restituzione per stimare ciascuna velocità finale. \nAd esempio, masse uguali di 1 kg che si muovono a velocità di +2 m/s e −1 m/s si scambiano in un urto elastico ideale, mentre la quantità di moto totale rimane 1 kg·m/s.","privacyQuestion":"I miei valori sono caricati?","privacyAnswer":"No. Il calcolo viene eseguito in questo browser; \ni valori non vengono caricati né salvati.","fields":{"mode":"Calcolo","momentumMode":"Solo quantità di moto totale","collisionMode":"Modella una collisione","mass1":"Oggetto 1 massa","mass2":"Oggetto 2 massa","massUnit":"Unità di massa","kilograms":"Chilogrammi (kg)","grams":"Grammi (g)","tonnes":"Tonnellate metriche (t)","velocity1":"Velocità iniziale oggetto 1","velocity2":"Velocità iniziale oggetto 2","speedUnit":"Unità di velocità","metersPerSecond":"Metri al secondo (m/s)","kilometersPerHour":"Chilometri orari (km/h)","feetPerSecond":"Piedi al secondo (ft/s)","restitution":"Coefficiente di restituzione (0–1)","accuracyNote":"Modello classico monodimensionale. \nLe velocità positive e negative mostrano la direzione. \nLe collisioni sono trattate come isolate: non vengono modellati impulsi esterni, rotazioni, dettagli di deformazione o effetti relativistici. \nUn valore pari a 1 è elastico ideale; \n0 è perfettamente anelastico. \nSi tratta di una stima educativa, non di una valutazione ingegneristica o di sicurezza."},"actions":{"calculate":"Calcola","reset":"Cancella","copy":"Copia risultato","example":"Prova la collisione di masse uguali","result":"Risultato del momento"},"messages":{"calculated":"Calcolo pronto.","checkInputs":"Immettere due masse positive, velocità con segno valide, unità supportate e un valore di restituzione compreso tra 0 e 1.","momentumBefore":"Momento totale prima della collisione","kineticEnergyBefore":"Energia cinetica totale prima della collisione","finalVelocity1":"Velocità finale oggetto 1","finalVelocity2":"Velocità finale oggetto 2","momentumAfter":"Momento totale dopo la collisione","kineticEnergyAfter":"Energia cinetica totale dopo l'urto","energyLoss":"Energia cinetica convertita o persa nel modello"},"additionalFaqs":[{"question":"Cosa significa una velocità negativa?","answer":"Significa che l'oggetto si muove nella direzione opposta rispetto alla direzione positiva che hai scelto. \nMantenere il segno quando si inseriscono entrambe le velocità; \ninfluenza la quantità di moto totale e il risultato della collisione."},{"question":"Cosa significa il coefficiente di restituzione?","answer":"Descrive la velocità relativa di separazione dopo un impatto unidimensionale rispetto alla velocità di avvicinamento. \nZero modella una collisione perfettamente anelastica; \nsi modella un urto elastico ideale. \nI materiali reali possono variare in base alle condizioni di impatto."},{"question":"In ogni urto la quantità di moto si conserva?","answer":"La quantità di moto totale è conservata in questo modello quando il sistema a due oggetti non ha alcun impulso esterno netto. \nLa calcolatrice mostra i valori prima e dopo in modo da poterli confrontare."},{"question":"Questa calcolatrice copre le collisioni angolari o rotanti?","answer":"No. Modella il moto solo su una linea retta. \nNon calcola angoli, rotazione, forma dell'oggetto, suono, dettagli di calore o deformazione."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"zh_tw":{"copyLanguage":"zh_tw","name":"動量計算器","title":"動量計算器免費 | UsefulVerse","description":"計算一維動量或對具有符號速度的兩個物體碰撞進行建模。免費且本地化。","intro":"求兩個沿一條直線移動的物體的總動量，或估計它們在碰撞後的速率。將每個方向設定為正速度或負速度，並選擇 0 到 1 之間的恢復係數。","howQuestion":"如何計算動量和碰撞速度？","howAnswer":"動量是質量乘以速度，p = mv，總和是兩個物體的有符號和。對於一維碰撞，該計算器使用恢復係數來估計每個最終速度。例如，在理想彈性碰撞中，以 +2 m/s 和 -1 m/s 移動的相同 1 kg 質量交換速度，而總動量仍為 1 kg·m/s。","privacyQuestion":"我的值是否已上傳？","privacyAnswer":"否。計算在此瀏覽器中運行；這些值不會上傳或保存。","fields":{"mode":"計算","momentumMode":"僅總動量","collisionMode":"模擬碰撞","mass1":"物體 1 質量","mass2":"物體 2 質量","massUnit":"質量單位","kilograms":"公斤 (kg)","grams":"克 (g)","tonnes":"公噸 (t)","velocity1":"物件 1 初始速度","velocity2":"物體 2 初始速度","speedUnit":"速度單位","metersPerSecond":"公尺每秒 (m/s)","kilometersPerHour":"公里每小時 (km/h)","feetPerSecond":"英尺每秒 (ft/s)","restitution":"恢復係數 (0–1)","accuracyNote":"一維經典模型。正速度和負速度顯示方向。碰撞被視為孤立的：沒有對外部脈衝、旋轉、變形細節或相對論效應進行建模。值為 1 為理想彈性； 0 是完全無彈性的。這是教育評估，而不是工程或安全評估。"},"actions":{"calculate":"計算","reset":"清除","copy":"複製結果","example":"嘗試等質量碰撞","result":"動量結果"},"messages":{"calculated":"計算就緒。","checkInputs":"輸入兩個正質量、有效的帶符號速度、支援的單位以及 0 到 1 之間的恢復值。","momentumBefore":"碰撞前總動量","kineticEnergyBefore":"碰撞前總動能","finalVelocity1":"物件 1 最終速度","finalVelocity2":"物件 2 最終速度","momentumAfter":"碰撞後總動量","kineticEnergyAfter":"碰撞後總動能","energyLoss":"模型中转换或损失的动能"},"additionalFaqs":[{"question":"負速度是什麼意思？","answer":"表示物体向与您选择的正方向相反的方向移动。输入两个速度时保留符号；它影响总动量和碰撞结果。"},{"question":"恢復係數是什麼意思？","answer":"描述一维撞击后与接近速度相比的相对分离速度。零模型完全非弹性碰撞；一种模型是理想的弹性碰撞。真實材料可能會因衝擊條件而異。"},{"question":"每次碰撞时动量守恒吗？","answer":"当双物体系统没有净外部冲量时，该模型中的总动量守恒。计算器会显示之前和之后的值，以便您可以比较它们。"},{"question":"此计算器是否涵盖倾斜或旋转碰撞？","answer":"否。它只模擬一條直線上的運動。它不计算角度、旋转、物体形状、声音、热量细节或变形。"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"bg":{"copyLanguage":"bg","name":"Калкулатор на инерция","title":"Безплатен калкулатор на инерция | UsefulVerse","description":"Изчислете едномерен импулс или моделирайте сблъсък на два обекта със скорости със знак. \nБезплатно и местно.","intro":"Намерете общия импулс за два обекта, движещи се по една линия, или преценете техните скорости след сблъсък. \nЗадайте всяка посока с положителна или отрицателна скорост и изберете коефициент на възстановяване от 0 до 1.","howQuestion":"Как изчислявате скоростта на импулса и сблъсъка?","howAnswer":"Импулсът е масата по скоростта, p = mv, а общата сума е сумата със знак за двата обекта. \nЗа едноизмерен сблъсък този калкулатор използва коефициента на възстановяване, за да оцени всяка крайна скорост. \nНапример, равни маси от 1 kg, движещи се с +2 m/s и −1 m/s, обменят скорости при идеален еластичен сблъсък, докато общият импулс остава 1 kg·m/s.","privacyQuestion":"Моите стойности качени ли са?","privacyAnswer":"Не. Изчислението се изпълнява в този браузър; \nстойностите не се качват или записват.","fields":{"mode":"Калкулация","momentumMode":"Само общ импулс","collisionMode":"Модел на сблъсък","mass1":"Обект 1 мас","mass2":"Обект 2 мас","massUnit":"Единица за маса","kilograms":"килограма (кг)","grams":"грама (g)","tonnes":"Метрични тонове (t)","velocity1":"Обект 1 начална скорост","velocity2":"Начална скорост на обект 2","speedUnit":"Единица за скорост","metersPerSecond":"Метри в секунда (m/s)","kilometersPerHour":"Километри в час (км/ч)","feetPerSecond":"Фута в секунда (ft/s)","restitution":"Коефициент на реституция (0–1)","accuracyNote":"Едноизмерен класически модел. \nПоложителните и отрицателните скорости показват посоката. \nСблъсъците се третират като изолирани: не се моделират външни импулси, въртене, детайли на деформация или релативистични ефекти. \nСтойност 1 е идеална еластичност; \n0 е съвършено нееластичен. \nТова е образователна оценка, а не инженерна оценка или оценка на безопасността."},"actions":{"calculate":"Изчисли","reset":"Ясно","copy":"Резултат от копиране","example":"Опитайте да се сблъскат равни маси","result":"Инерционен резултат"},"messages":{"calculated":"Изчислението е готово.","checkInputs":"Въведете две положителни маси, валидни скорости със знак, поддържани единици и възстановена стойност от 0 до 1.","momentumBefore":"Общ импулс преди сблъсък","kineticEnergyBefore":"Обща кинетична енергия преди сблъсък","finalVelocity1":"Обект 1 крайна скорост","finalVelocity2":"Обект 2 крайна скорост","momentumAfter":"Общ импулс след сблъсък","kineticEnergyAfter":"Обща кинетична енергия след сблъсък","energyLoss":"Кинетична енергия, преобразувана или загубена в модела"},"additionalFaqs":[{"question":"Какво означава отрицателна скорост?","answer":"Това означава, че обектът се движи в обратна посока от положителната посока, която сте избрали. \nЗапазете знака, когато въвеждате и двете скорости; \nвлияе върху общия импулс и резултата от сблъсъка."},{"question":"Какво означава коефициентът на реституция?","answer":"Описва относителната скорост на отделяне след едномерен удар в сравнение със скоростта на приближаване. \nНула моделира идеално нееластичен сблъсък; \nчовек моделира идеален еластичен сблъсък. \nРеалните материали могат да варират в зависимост от условията на удар."},{"question":"Инерцията запазва ли се при всеки сблъсък?","answer":"Общият импулс се запазва в този модел, когато системата от два обекта няма нетен външен импулс. \nКалкулаторът показва стойности преди и след, за да можете да ги сравните."},{"question":"Този калкулатор обхваща ли сблъсъци под ъгъл или въртене?","answer":"Не. Моделира движение само по една права линия. \nНе изчислява ъгли, ротация, форма на обект, звук, топлинни детайли или деформация."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ca":{"copyLanguage":"ca","name":"Calculadora d'impuls","title":"Calculadora de Momentum Gratis | UsefulVerse","description":"Calcula el moment unidimensional o modela una col·lisió de dos objectes amb velocitats signades. \nGratuït i local.","intro":"Troba l'impuls total de dos objectes que es mouen al llarg d'una línia o estima la seva velocitat després d'una col·lisió. \nEstableix cada direcció amb una velocitat positiva o negativa i tria un coeficient de restitució de 0 a 1.","howQuestion":"Com calculeu l'impuls i les velocitats de col·lisió?","howAnswer":"El moment és la massa per la velocitat, p = mv, i el total és la suma amb signes dels dos objectes. \nPer a una col·lisió unidimensional, aquesta calculadora utilitza el coeficient de restitució per estimar cada velocitat final. \nPer exemple, masses iguals d'1 kg que es mouen a velocitats d'intercanvi de +2 m/s i -1 m/s en una col·lisió elàstica ideal, mentre que el moment total es manté en 1 kg·m/s.","privacyQuestion":"S'han penjat els meus valors?","privacyAnswer":"No. El càlcul s'executa en aquest navegador; \nels valors no es carreguen ni es guarden.","fields":{"mode":"Càlcul","momentumMode":"Moment total només","collisionMode":"Modelar una col·lisió","mass1":"Objecte 1 massa","mass2":"Objecte 2 massa","massUnit":"Unitat de massa","kilograms":"quilograms (kg)","grams":"grams (g)","tonnes":"Tones mètriques (t)","velocity1":"Objecte 1 velocitat inicial","velocity2":"Objecte 2 velocitat inicial","speedUnit":"Unitat de velocitat","metersPerSecond":"metres per segon (m/s)","kilometersPerHour":"Quilòmetres per hora (km/h)","feetPerSecond":"peus per segon (ft/s)","restitution":"Coeficient de restitució (0–1)","accuracyNote":"Model clàssic unidimensional. \nLes velocitats positives i negatives mostren la direcció. \nLes col·lisions es tracten com aïllades: no es modela cap impuls extern, gir, detall de deformació o efectes relativistes. \nUn valor d'1 és elàstic ideal; \n0 és perfectament inelàstic. \nAquesta és una estimació educativa, no una avaluació d'enginyeria o seguretat."},"actions":{"calculate":"Calcula","reset":"Clar","copy":"Copia el resultat","example":"Intenteu xocar masses iguals","result":"Resultat impuls"},"messages":{"calculated":"Càlcul preparat.","checkInputs":"Introduïu dues masses positives, velocitats amb signe vàlides, unitats suportades i un valor de restitució de 0 a 1.","momentumBefore":"Moment total abans de la col·lisió","kineticEnergyBefore":"Energia cinètica total abans de la col·lisió","finalVelocity1":"Objecte 1 velocitat final","finalVelocity2":"Objecte 2 velocitat final","momentumAfter":"Moment total després de la col·lisió","kineticEnergyAfter":"Energia cinètica total després de la col·lisió","energyLoss":"Energia cinètica convertida o perduda en el model"},"additionalFaqs":[{"question":"Què vol dir una velocitat negativa?","answer":"Significa que l'objecte es mou en la direcció oposada a la direcció positiva que heu triat. \nMantingueu el signe quan introduïu les dues velocitats; \nafecta el moment total i el resultat de la col·lisió."},{"question":"Què vol dir el coeficient de restitució?","answer":"Descriu la velocitat relativa de separació després d'un impacte unidimensional en comparació amb la velocitat d'aproximació. \nZero modela una col·lisió perfectament inelàstica; \nun modela una col·lisió elàstica ideal. \nEls materials reals poden variar segons les condicions d'impacte."},{"question":"Es conserva el moment en cada xoc?","answer":"El moment total es conserva en aquest model quan el sistema de dos objectes no té cap impuls extern net. \nLa calculadora mostra els valors abans i després perquè pugueu comparar-los."},{"question":"Aquesta calculadora cobreix col·lisions angulades o giratòries?","answer":"No. Modela el moviment només en una línia recta. \nNo calcula angles, rotació, forma de l'objecte, so, detalls de calor o deformació."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"nl":{"copyLanguage":"nl","name":"Momentumcalculator","title":"Momentumcalculator gratis | UsefulVerse","description":"Bereken een eendimensionaal momentum of modelleer een botsing tussen twee objecten met getekende snelheden. \nGratis en lokaal.","intro":"Vind het totale momentum van twee objecten die langs één lijn bewegen, of schat hun snelheid na een botsing. \nStel elke richting in met een positieve of negatieve snelheid en kies een restitutiecoëfficiënt van 0 tot 1.","howQuestion":"Hoe bereken je momentum en botsingssnelheden?","howAnswer":"Momentum is massa maal snelheid, p = mv, en het totaal is de som met teken voor beide objecten. \nVoor een eendimensionale botsing gebruikt deze calculator de restitutiecoëfficiënt om elke eindsnelheid te schatten. \nGelijke massa's van 1 kg die met +2 m/s en -1 m/s bewegen, wisselen bijvoorbeeld snelheden uit in een ideale elastische botsing, terwijl het totale momentum 1 kg · m/s blijft.","privacyQuestion":"Zijn mijn waarden geüpload?","privacyAnswer":"Nee. De berekening wordt in deze browser uitgevoerd; \nde waarden worden niet geüpload of opgeslagen.","fields":{"mode":"Berekening","momentumMode":"Alleen totaal momentum","collisionMode":"Modelleer een botsing","mass1":"Object 1 massa","mass2":"Object 2 massa","massUnit":"Massa-eenheid","kilograms":"Kilogram (kg)","grams":"Gram (g)","tonnes":"Metrische ton (t)","velocity1":"Beginsnelheid object 1","velocity2":"Beginsnelheid object 2","speedUnit":"Snelheidseenheid","metersPerSecond":"Meter per seconde (m/s)","kilometersPerHour":"Kilometer per uur (km/u)","feetPerSecond":"Voet per seconde (ft/s)","restitution":"Restitutiecoëfficiënt (0–1)","accuracyNote":"Eendimensionaal klassiek model. \nPositieve en negatieve snelheden geven richting aan. \nBotsingen worden als geïsoleerd beschouwd: er worden geen externe impulsen, rotaties, vervormingsdetails of relativistische effecten gemodelleerd. \nEen waarde van 1 is ideaal elastisch; \n0 is volkomen inelastisch. \nDit is een educatieve schatting, geen technische of veiligheidsbeoordeling."},"actions":{"calculate":"Bereken","reset":"Helder","copy":"Resultaat kopiëren","example":"Probeer gelijke massa's tegen elkaar te laten botsen","result":"Momentumresultaat"},"messages":{"calculated":"Berekening gereed.","checkInputs":"Voer twee positieve massa's, geldige getekende snelheden, ondersteunde eenheden en een restitutiewaarde van 0 tot 1 in.","momentumBefore":"Totale momentum vóór botsing","kineticEnergyBefore":"Totale kinetische energie vóór botsing","finalVelocity1":"Eindsnelheid object 1","finalVelocity2":"Eindsnelheid object 2","momentumAfter":"Totaal momentum na botsing","kineticEnergyAfter":"Totale kinetische energie na botsing","energyLoss":"Kinetische energie omgezet of verloren gegaan in het model"},"additionalFaqs":[{"question":"Wat betekent een negatieve snelheid?","answer":"Dit betekent dat het object in de tegenovergestelde richting beweegt van de positieve richting die u hebt gekozen. \nHoud bij het invoeren van beide snelheden het bord aan; \nhet beïnvloedt het totale momentum en het botsingsresultaat."},{"question":"Wat betekent de restitutiecoëfficiënt?","answer":"Het beschrijft de relatieve scheidingssnelheid na een eendimensionale impact vergeleken met de naderende snelheid. \nZero modelleert een volkomen inelastische botsing; \nmen modelleert een ideale elastische botsing. \nEchte materialen kunnen variëren afhankelijk van de impactomstandigheden."},{"question":"Blijft het momentum behouden bij elke botsing?","answer":"Het totale momentum blijft in dit model behouden wanneer het tweeobjectsysteem geen netto externe impuls heeft. \nDe rekenmachine toont waarden voor en na, zodat u ze kunt vergelijken."},{"question":"Bestrijkt deze rekenmachine schuine of roterende botsingen?","answer":"Nee. Het modelleert beweging slechts op één rechte lijn. \nHet berekent geen hoeken, rotatie, objectvorm, geluid, warmtedetails of vervorming."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"el":{"copyLanguage":"el","name":"Υπολογιστής ορμής","title":"Υπολογιστής ορμής Δωρεάν | UsefulVerse","description":"Υπολογίστε τη μονοδιάστατη ορμή ή μοντελοποιήστε μια σύγκρουση δύο αντικειμένων με σηματοδοτημένες ταχύτητες. \nΔωρεάν και τοπικό.","intro":"Βρείτε τη συνολική ορμή για δύο αντικείμενα που κινούνται κατά μήκος μιας γραμμής ή υπολογίστε τις ταχύτητες τους μετά από σύγκρουση. \nΟρίστε κάθε κατεύθυνση με θετική ή αρνητική ταχύτητα και επιλέξτε έναν συντελεστή επαναφοράς από 0 έως 1.","howQuestion":"Πώς υπολογίζετε την ορμή και τις ταχύτητες σύγκρουσης;","howAnswer":"Η ορμή είναι η μάζα επί την ταχύτητα, p = mv, και το σύνολο είναι το υποσημασμένο άθροισμα και για τα δύο αντικείμενα. \nΓια μια μονοδιάστατη σύγκρουση, αυτή η αριθμομηχανή χρησιμοποιεί τον συντελεστή επαναφοράς για να εκτιμήσει κάθε τελική ταχύτητα. \nΓια παράδειγμα, ίσες μάζες 1 kg που κινούνται με +2 m/s και −1 m/s ανταλλάσσουν ταχύτητες σε μια ιδανική ελαστική σύγκρουση, ενώ η συνολική ορμή παραμένει 1 kg·m/s.","privacyQuestion":"Έχουν μεταφορτωθεί οι τιμές μου;","privacyAnswer":"Όχι. Ο υπολογισμός εκτελείται σε αυτό το πρόγραμμα περιήγησης. \nοι τιμές δεν μεταφορτώνονται ούτε αποθηκεύονται.","fields":{"mode":"Υπολογισμός","momentumMode":"Μόνο συνολική ορμή","collisionMode":"Μοντέλο σύγκρουσης","mass1":"Αντικείμενο 1 μάζα","mass2":"Αντικείμενο 2 μάζα","massUnit":"Μαζική μονάδα","kilograms":"κιλά (kg)","grams":"γραμμάρια (g)","tonnes":"Μετρικοί τόνοι (t)","velocity1":"Αρχική ταχύτητα αντικειμένου 1","velocity2":"Αρχική ταχύτητα αντικειμένου 2","speedUnit":"Μονάδα ταχύτητας","metersPerSecond":"Μέτρα ανά δευτερόλεπτο (m/s)","kilometersPerHour":"Χιλιόμετρα ανά ώρα (χλμ/ώρα)","feetPerSecond":"Πόδια ανά δευτερόλεπτο (ft/s)","restitution":"Συντελεστής αποκατάστασης (0–1)","accuracyNote":"Μονοδιάστατο κλασικό μοντέλο. \nΟι θετικές και οι αρνητικές ταχύτητες δείχνουν κατεύθυνση. \nΟι συγκρούσεις αντιμετωπίζονται ως μεμονωμένες: δεν μοντελοποιείται καμία εξωτερική ώθηση, περιστροφή, λεπτομέρεια παραμόρφωσης ή σχετικιστικά αποτελέσματα. \nΗ τιμή 1 είναι ιδανικό ελαστικό. \nΤο 0 είναι απολύτως ανελαστικό. \nΑυτή είναι μια εκπαιδευτική εκτίμηση, όχι μια αξιολόγηση μηχανικής ή ασφάλειας."},"actions":{"calculate":"Υπολογίστε","reset":"Καθαρισμός","copy":"Αντιγραφή αποτελέσματος","example":"Δοκιμάστε ίσες μάζες σύγκρουσης","result":"Αποτέλεσμα ορμής"},"messages":{"calculated":"Έτοιμος ο υπολογισμός.","checkInputs":"Εισαγάγετε δύο θετικές μάζες, έγκυρες υπογεγραμμένες ταχύτητες, υποστηριζόμενες μονάδες και μια τιμή επαναφοράς από το 0 έως το 1.","momentumBefore":"Συνολική ορμή πριν από τη σύγκρουση","kineticEnergyBefore":"Ολική κινητική ενέργεια πριν από τη σύγκρουση","finalVelocity1":"Αντικείμενο 1 τελική ταχύτητα","finalVelocity2":"Αντικείμενο 2 Τελική ταχύτητα","momentumAfter":"Συνολική ορμή μετά από σύγκρουση","kineticEnergyAfter":"Ολική κινητική ενέργεια μετά από σύγκρουση","energyLoss":"Μετατροπή ή απώλεια κινητικής ενέργειας στο μοντέλο"},"additionalFaqs":[{"question":"Τι σημαίνει αρνητική ταχύτητα;","answer":"Σημαίνει ότι το αντικείμενο κινείται προς την αντίθετη κατεύθυνση από τη θετική κατεύθυνση που επιλέξατε. \nΚρατήστε το σύμβολο όταν εισάγετε και τις δύο ταχύτητες. \nεπηρεάζει τη συνολική ορμή και το αποτέλεσμα της σύγκρουσης."},{"question":"Τι σημαίνει ο συντελεστής αποκατάστασης;","answer":"Περιγράφει τη σχετική ταχύτητα διαχωρισμού μετά από μονοδιάστατη κρούση σε σύγκριση με την ταχύτητα προσέγγισης. \nZero μοντέλα μια τέλεια ανελαστική σύγκρουση. \nκάποιος διαμορφώνει μια ιδανική ελαστική σύγκρουση. \nΤα πραγματικά υλικά μπορεί να διαφέρουν ανάλογα με τις συνθήκες πρόσκρουσης."},{"question":"Διατηρείται η ορμή σε κάθε σύγκρουση;","answer":"Η συνολική ορμή διατηρείται σε αυτό το μοντέλο όταν το σύστημα δύο αντικειμένων δεν έχει καθαρή εξωτερική ώθηση. \nΗ αριθμομηχανή εμφανίζει τιμές πριν και μετά, ώστε να μπορείτε να τις συγκρίνετε."},{"question":"Αυτή η αριθμομηχανή καλύπτει γωνιακές ή περιστροφικές συγκρούσεις;","answer":"Όχι. Μοντελοποιεί την κίνηση μόνο σε μία ευθεία γραμμή. \nΔεν υπολογίζει γωνίες, περιστροφή, σχήμα αντικειμένου, ήχο, λεπτομέρειες θερμότητας ή παραμόρφωση."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ms":{"copyLanguage":"ms","name":"Kalkulator Momentum","title":"Kalkulator Momentum Percuma | UsefulVerse","description":"Kira momentum satu dimensi atau modelkan perlanggaran dua objek dengan kelajuan yang ditandatangani. \nPercuma dan tempatan.","intro":"Cari jumlah momentum untuk dua objek yang bergerak sepanjang satu garisan atau anggarkan kelajuannya selepas perlanggaran. \nTetapkan setiap arah dengan halaju positif atau negatif dan pilih pekali pengembalian daripada 0 hingga 1.","howQuestion":"Bagaimanakah anda mengira kelajuan momentum dan perlanggaran?","howAnswer":"Momentum ialah jisim kali halaju, p = mv, dan jumlahnya ialah jumlah bertanda bagi kedua-dua objek. \nUntuk perlanggaran satu dimensi, kalkulator ini menggunakan pekali pengembalian untuk menganggar setiap halaju akhir. \nSebagai contoh, sama 1 kg jisim bergerak pada +2 m/s dan −1 m/s kelajuan pertukaran dalam perlanggaran kenyal ideal, manakala jumlah momentum kekal 1 kg·m/s.","privacyQuestion":"Adakah nilai saya dimuat naik?","privacyAnswer":"Tidak. Pengiraan dijalankan dalam pelayar ini; \nnilai tidak dimuat naik atau disimpan.","fields":{"mode":"Pengiraan","momentumMode":"Jumlah momentum sahaja","collisionMode":"Model perlanggaran","mass1":"Objek 1 jisim","mass2":"Objek 2 jisim","massUnit":"Unit jisim","kilograms":"Kilogram (kg)","grams":"Gram (g)","tonnes":"Tan metrik (t)","velocity1":"Objek 1 halaju awal","velocity2":"Objek 2 halaju awal","speedUnit":"Unit halaju","metersPerSecond":"Meter sesaat (m/s)","kilometersPerHour":"Kilometer sejam (km/j)","feetPerSecond":"Kaki sesaat (kaki/s)","restitution":"Pekali pengembalian (0–1)","accuracyNote":"Model klasik satu dimensi. \nHalaju positif dan negatif menunjukkan arah. \nPerlanggaran dianggap sebagai terpencil: tiada impuls luaran, putaran, perincian ubah bentuk atau kesan relativistik dimodelkan. \nNilai 1 ialah anjal ideal; \n0 adalah tidak anjal sempurna. \nIni adalah anggaran pendidikan, bukan penilaian kejuruteraan atau keselamatan."},"actions":{"calculate":"Kira","reset":"Jelas","copy":"Salin keputusan","example":"Cuba jisim yang sama berlanggar","result":"Keputusan momentum"},"messages":{"calculated":"Pengiraan sedia.","checkInputs":"Masukkan dua jisim positif, halaju bertanda yang sah, unit disokong dan nilai pengembalian daripada 0 hingga 1.","momentumBefore":"Jumlah momentum sebelum perlanggaran","kineticEnergyBefore":"Jumlah tenaga kinetik sebelum perlanggaran","finalVelocity1":"Objek 1 halaju akhir","finalVelocity2":"Objek 2 halaju akhir","momentumAfter":"Jumlah momentum selepas perlanggaran","kineticEnergyAfter":"Jumlah tenaga kinetik selepas perlanggaran","energyLoss":"Tenaga kinetik ditukar atau hilang dalam model"},"additionalFaqs":[{"question":"Apakah maksud halaju negatif?","answer":"Ini bermakna objek bergerak ke arah bertentangan dari arah positif yang anda pilih. \nSimpan tanda apabila memasuki kedua-dua halaju; \nia menjejaskan jumlah momentum dan hasil perlanggaran."},{"question":"Apakah maksud pekali pengembalian?","answer":"Ia menerangkan kelajuan pemisahan relatif selepas kesan satu dimensi berbanding dengan kelajuan yang menghampiri. \nSifar memodelkan perlanggaran tidak anjal sempurna; \nsatu model perlanggaran anjal yang ideal. \nBahan sebenar boleh berbeza mengikut keadaan impak."},{"question":"Adakah momentum dikekalkan dalam setiap perlanggaran?","answer":"Jumlah momentum dikekalkan dalam model ini apabila sistem dua objek tidak mempunyai impuls luaran bersih. \nKalkulator menunjukkan nilai sebelum dan selepas supaya anda boleh membandingkannya."},{"question":"Adakah kalkulator ini meliputi perlanggaran bersudut atau berputar?","answer":"Tidak. Ia memodelkan gerakan pada satu garis lurus sahaja. \nIa tidak mengira sudut, putaran, bentuk objek, bunyi, butiran haba atau ubah bentuk."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"pl":{"copyLanguage":"pl","name":"Kalkulator pędu","title":"Kalkulator pędu Darmowy | UsefulVerse","description":"Oblicz jednowymiarowy pęd lub zamodeluj zderzenie dwóch obiektów ze znakowanymi prędkościami. \nBezpłatne i lokalne.","intro":"Znajdź całkowity pęd dwóch obiektów poruszających się po jednej linii lub oszacuj ich prędkości po zderzeniu. \nUstaw każdy kierunek z dodatnią lub ujemną prędkością i wybierz współczynnik restytucji od 0 do 1.","howQuestion":"Jak obliczyć pęd i prędkość zderzenia?","howAnswer":"Pęd to masa razy prędkość, p = mv, a suma to suma ze znakiem obu obiektów. \nW przypadku kolizji jednowymiarowej kalkulator ten wykorzystuje współczynnik restytucji do oszacowania każdej prędkości końcowej. \nNa przykład równe masy 1 kg poruszające się z prędkościami +2 m/s i -1 m/s wymieniają się podczas idealnego zderzenia sprężystego, podczas gdy całkowity pęd pozostaje 1 kg·m/s.","privacyQuestion":"Czy moje wartości zostały przesłane?","privacyAnswer":"Nie. Kalkulacja przebiega w tej przeglądarce; \nwartości nie są przesyłane ani zapisywane.","fields":{"mode":"Obliczenia","momentumMode":"Tylko całkowity pęd","collisionMode":"Modeluj kolizję","mass1":"Obiekt 1 masa","mass2":"Obiekt 2 masa","massUnit":"Jednostka masy","kilograms":"Kilogramy (kg)","grams":"Gramów (g)","tonnes":"Tony metryczne (t)","velocity1":"Obiekt 1 prędkość początkowa","velocity2":"Prędkość początkowa obiektu 2","speedUnit":"Jednostka prędkości","metersPerSecond":"Metrów na sekundę (m/s)","kilometersPerHour":"Kilometry na godzinę (km/h)","feetPerSecond":"Stopy na sekundę (ft/s)","restitution":"Współczynnik restytucji (0–1)","accuracyNote":"Jednowymiarowy model klasyczny. \nPrędkości dodatnie i ujemne wskazują kierunek. \nZderzenia są traktowane jako izolowane: nie modeluje się żadnych zewnętrznych impulsów, rotacji, szczegółów deformacji ani efektów relatywistycznych. \nWartość 1 oznacza idealną elastyczność; \n0 jest doskonale niesprężyste. \nJest to ocena edukacyjna, a nie ocena inżynieryjna lub bezpieczeństwa."},"actions":{"calculate":"Oblicz","reset":"Jasne","copy":"Skopiuj wynik","example":"Spróbuj zderzenia równych mas","result":"Wynik pędu"},"messages":{"calculated":"Kalkulacja gotowa.","checkInputs":"Wprowadź dwie masy dodatnie, prawidłowe prędkości ze znakiem, obsługiwane jednostki i wartość restytucji od 0 do 1.","momentumBefore":"Całkowity pęd przed zderzeniem","kineticEnergyBefore":"Całkowita energia kinetyczna przed zderzeniem","finalVelocity1":"Obiekt 1 prędkość końcowa","finalVelocity2":"Obiekt 2 Prędkość końcowa","momentumAfter":"Całkowity pęd po zderzeniu","kineticEnergyAfter":"Całkowita energia kinetyczna po zderzeniu","energyLoss":"Energia kinetyczna przekształcona lub utracona w modelu"},"additionalFaqs":[{"question":"Co oznacza prędkość ujemna?","answer":"Oznacza to, że obiekt porusza się w kierunku przeciwnym do wybranego kierunku dodatniego. \nPrzy wprowadzaniu obu prędkości należy zachować znak; \nwpływa to na pęd całkowity i wynik zderzenia."},{"question":"Co oznacza współczynnik restytucji?","answer":"Opisuje względną prędkość oddzielania po jednowymiarowym uderzeniu w porównaniu z prędkością zbliżania się. \nZero modeluje doskonale niesprężyste zderzenie; \njeden modeluje idealne zderzenie sprężyste. \nRzeczywiste materiały mogą się różnić w zależności od warunków uderzenia."},{"question":"Czy pęd jest zachowany w każdym zderzeniu?","answer":"W tym modelu całkowity pęd jest zachowany, gdy układ dwóch obiektów nie ma wypadkowego impulsu zewnętrznego. \nKalkulator pokazuje wartości przed i po, dzięki czemu można je porównać."},{"question":"Czy ten kalkulator uwzględnia kolizje pod kątem lub podczas obrotu?","answer":"Nie. Modeluje ruch tylko po jednej linii prostej. \nNie oblicza kątów, rotacji, kształtu obiektu, dźwięku, szczegółów cieplnych ani deformacji."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"sv":{"copyLanguage":"sv","name":"Momentumkalkylator","title":"Momentum Calculator Gratis | UsefulVerse","description":"Beräkna endimensionell fart eller modellera en tvåobjektskollision med markerade hastigheter. \nGratis och lokalt.","intro":"Hitta total fart för två objekt som rör sig längs en linje, eller uppskatta deras hastigheter efter en kollision. \nStäll in varje riktning med en positiv eller negativ hastighet och välj en restitutionskoefficient från 0 till 1.","howQuestion":"Hur beräknar man momentum och kollisionshastigheter?","howAnswer":"Momentum är massa gånger hastighet, p = mv, och summan är den signerade summan för båda objekten. \nFör en endimensionell kollision använder denna kalkylator restitutionskoefficienten för att uppskatta varje sluthastighet. \nTill exempel, lika 1 kg massor som rör sig med +2 m/s och −1 m/s utbyteshastigheter vid en idealisk elastisk kollision, medan den totala rörelsemängden förblir 1 kg·m/s.","privacyQuestion":"Är mina värden uppladdade?","privacyAnswer":"Nej. Beräkningen körs i den här webbläsaren; \nvärdena laddas inte upp eller sparas.","fields":{"mode":"Beräkning","momentumMode":"Endast total fart","collisionMode":"Modellera en kollision","mass1":"Objekt 1 massa","mass2":"Objekt 2 massa","massUnit":"Massenhet","kilograms":"Kilogram (kg)","grams":"gram (g)","tonnes":"Metriska ton (t)","velocity1":"Objekt 1 initial hastighet","velocity2":"Objekt 2 initial hastighet","speedUnit":"Hastighetsenhet","metersPerSecond":"Meter per sekund (m/s)","kilometersPerHour":"Kilometer per timme (km/h)","feetPerSecond":"fot per sekund (ft/s)","restitution":"Restitutionskoefficient (0–1)","accuracyNote":"Endimensionell klassisk modell. \nPositiva och negativa hastigheter visar riktning. \nKollisioner behandlas som isolerade: ingen extern impuls, rotation, deformationsdetaljer eller relativistiska effekter modelleras. \nEtt värde på 1 är idealisk elastisk; \n0 är helt oelastisk. \nDetta är en pedagogisk uppskattning, inte en ingenjörs- eller säkerhetsbedömning."},"actions":{"calculate":"Beräkna","reset":"Klar","copy":"Kopiera resultat","example":"Prova att krocka med lika massor","result":"Momentumresultat"},"messages":{"calculated":"Beräkning klar.","checkInputs":"Ange två positiva massor, giltiga teckenhastigheter, stödda enheter och ett återställande värde från 0 till 1.","momentumBefore":"Total fart före kollision","kineticEnergyBefore":"Total kinetisk energi före kollision","finalVelocity1":"Objekt 1 sluthastighet","finalVelocity2":"Objekt 2 sluthastighet","momentumAfter":"Total fart efter kollision","kineticEnergyAfter":"Total kinetisk energi efter kollision","energyLoss":"Kinetisk energi omvandlad eller förlorad i modellen"},"additionalFaqs":[{"question":"Vad betyder en negativ hastighet?","answer":"Det betyder att objektet rör sig i motsatt riktning från den positiva riktning du valde. \nBehåll tecknet när du anger båda hastigheterna; \ndet påverkar total fart och kollisionsresultatet."},{"question":"Vad betyder restitutionskoefficienten?","answer":"Den beskriver den relativa separeringshastigheten efter en endimensionell kollision jämfört med den närmande hastigheten. \nZero modellerar en perfekt oelastisk kollision; \nman modellerar en idealisk elastisk kollision. \nVerkliga material kan variera med påverkan."},{"question":"Bevaras momentum vid varje kollision?","answer":"Totalt momentum bevaras i denna modell när tvåobjektssystemet inte har någon extern nettoimpuls. \nKalkylatorn visar värden före och efter så att du kan jämföra dem."},{"question":"Täcker denna kalkylator vinklade eller roterande kollisioner?","answer":"Nej. Den modellerar endast rörelse på en rak linje. \nDen beräknar inte vinklar, rotation, föremålsform, ljud, värmedetaljer eller deformation."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"th":{"copyLanguage":"th","name":"เครื่องคำนวณโมเมนตัม","title":"เครื่องคำนวณโมเมนตัม ฟรี | UsefulVerse","description":"คำนวณโมเมนตัมหนึ่งมิติหรือจำลองการชนกันของวัตถุสองชิ้นด้วยความเร็วที่กำหนด \nฟรีและท้องถิ่น","intro":"ค้นหาโมเมนตัมรวมของวัตถุสองชิ้นที่เคลื่อนที่ในเส้นเดียว หรือประมาณความเร็วหลังจากการชนกัน \nกำหนดแต่ละทิศทางด้วยความเร็วบวกหรือลบ และเลือกค่าสัมประสิทธิ์การชดใช้ตั้งแต่ 0 ถึง 1","howQuestion":"คุณคำนวณโมเมนตัมและความเร็วการชนอย่างไร?","howAnswer":"โมเมนตัมคือมวลคูณความเร็ว p = mv และผลรวมคือผลรวมที่ลงนามของวัตถุทั้งสอง \nสำหรับการชนกันในมิติเดียว เครื่องคำนวณนี้จะใช้ค่าสัมประสิทธิ์การชดตัวเพื่อประมาณความเร็วสุดท้ายแต่ละอัน \nตัวอย่างเช่น มวล 1 กิโลกรัมที่เท่ากันซึ่งเคลื่อนที่ที่ +2 m/s และ −1 m/s มีความเร็วแลกเปลี่ยนในการชนแบบยืดหยุ่นในอุดมคติ ในขณะที่โมเมนตัมทั้งหมดยังคงอยู่ที่ 1 kg·m/s","privacyQuestion":"ค่าของฉันถูกอัปโหลดหรือไม่","privacyAnswer":"ไม่ การคำนวณทำงานในเบราว์เซอร์นี้ \nค่าจะไม่ถูกอัพโหลดหรือบันทึก\n\nการคำนวณ","fields":{"mode":"Calculation","momentumMode":"โมเมนตัมรวมเท่านั้น","collisionMode":"แบบจำลองการชนกัน","mass1":"วัตถุ 1 มวล","mass2":"วัตถุ 2 มวล","massUnit":"หน่วยมวล","kilograms":"กิโลกรัม (กก.)","grams":"กรัม (ก.)","tonnes":"เมตริกตัน (t)","velocity1":"ความเร็วเริ่มต้นของวัตถุ 1","velocity2":"ความเร็วเริ่มต้นของวัตถุ 2","speedUnit":"หน่วยความเร็ว","metersPerSecond":"เมตรต่อวินาที (m/s)","kilometersPerHour":"กิโลเมตรต่อชั่วโมง (km/h)","feetPerSecond":"ฟุตต่อวินาที (ft/s)","restitution":"ค่าสัมประสิทธิ์การชดใช้ (0–1)","accuracyNote":"โมเดลคลาสสิกหนึ่งมิติ \nความเร็วบวกและลบแสดงทิศทาง \nการชนจะถือว่าแยกออกจากกัน: ไม่มีการสร้างแบบจำลองแรงกระตุ้นภายนอก การหมุน รายละเอียดการเสียรูป หรือผลกระทบเชิงสัมพัทธภาพ \nค่า 1 คือความยืดหยุ่นในอุดมคติ \n0 เป็นความไม่ยืดหยุ่นอย่างสมบูรณ์ \nนี่เป็นการประเมินทางการศึกษา ไม่ใช่การประเมินทางวิศวกรรมหรือความปลอดภัย"},"actions":{"calculate":"คำนวณ","reset":"เคลียร์","copy":"ผลการคัดลอก","example":"ลองชนกันด้วยมวลเท่ากัน","result":"ผลโมเมนตัม"},"messages":{"calculated":"คำนวณพร้อม","checkInputs":"ป้อนมวลบวกสองค่า ความเร็วที่เซ็นชื่อที่ถูกต้อง หน่วยที่รองรับ และค่าการชดใช้ตั้งแต่ 0 ถึง 1","momentumBefore":"โมเมนตัมรวมก่อนชน","kineticEnergyBefore":"พลังงานจลน์ทั้งหมดก่อนชน","finalVelocity1":"ความเร็วสุดท้ายของวัตถุ 1","finalVelocity2":"ความเร็วสุดท้ายของวัตถุ 2","momentumAfter":"โมเมนตัมรวมหลังจากการชน","kineticEnergyAfter":"พลังงานจลน์ทั้งหมดหลังการชน","energyLoss":"พลังงานจลน์ที่ถูกแปลงหรือสูญหายในแบบจำลอง"},"additionalFaqs":[{"question":"ความเร็วลบหมายความว่าอย่างไร","answer":"หมายความว่าวัตถุเคลื่อนที่ไปในทิศทางตรงกันข้ามจากทิศทางบวกที่คุณเลือก \nเก็บป้ายไว้เมื่อเข้าสู่ความเร็วทั้งสอง \nมันส่งผลต่อโมเมนตัมรวมและผลการชน"},{"question":"ค่าสัมประสิทธิ์การชดใช้หมายความว่าอย่างไร","answer":"อธิบายความเร็วการแยกสัมพัทธ์หลังจากการชนในมิติเดียวเมื่อเปรียบเทียบกับความเร็วที่กำลังเข้าใกล้ \nศูนย์จำลองการชนที่ไม่ยืดหยุ่นอย่างสมบูรณ์ \nแบบจำลองหนึ่งเป็นการชนแบบยืดหยุ่นในอุดมคติ \nวัสดุจริงอาจแตกต่างกันไปตามสภาวะการกระแทก"},{"question":"โมเมนตัมจะสงวนไว้ในการชนทุกครั้งหรือไม่?","answer":"โมเมนตัมรวมจะถูกสงวนไว้ในแบบจำลองนี้ เมื่อระบบสองวัตถุไม่มีแรงกระตุ้นภายนอกสุทธิ \nเครื่องคิดเลขจะแสดงค่าก่อนและหลังเพื่อให้คุณสามารถเปรียบเทียบได้"},{"question":"เครื่องคิดเลขนี้ครอบคลุมการชนแบบทำมุมหรือแบบหมุนหรือไม่?","answer":"ไม่ใช่ มันจำลองการเคลื่อนที่บนเส้นตรงเส้นเดียวเท่านั้น \nมันไม่ได้คำนวณมุม การหมุน รูปร่างของวัตถุ เสียง รายละเอียดความร้อน หรือการเสียรูป"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"uk":{"copyLanguage":"uk","name":"Калькулятор моменту","title":"Безкоштовний калькулятор імпульсу | UsefulVerse","description":"Обчислити одновимірний імпульс або змоделювати зіткнення двох об’єктів зі знаковими швидкостями. \nБезкоштовно та місцево.","intro":"Знайдіть загальний імпульс для двох об’єктів, що рухаються вздовж однієї лінії, або оцініть їхні швидкості після зіткнення. \nВстановіть для кожного напрямку позитивну або негативну швидкість і виберіть коефіцієнт відновлення від 0 до 1.","howQuestion":"Як обчислити імпульс і швидкість зіткнення?","howAnswer":"Імпульс — це маса, помножена на швидкість, p = mv, а загальна сума — це сума зі знаком для обох об’єктів. \nДля одновимірного зіткнення цей калькулятор використовує коефіцієнт відновлення для оцінки кожної кінцевої швидкості. \nНаприклад, маси масою 1 кг, що рухаються зі швидкістю +2 м/с і −1 м/с, обмінюються швидкостями в ідеальному пружному зіткненні, тоді як загальний імпульс залишається 1 кг·м/с.","privacyQuestion":"Чи завантажено мої значення?","privacyAnswer":"Ні. Розрахунок виконується в цьому браузері; \nзначення не завантажуються і не зберігаються.","fields":{"mode":"Розрахунок","momentumMode":"Тільки загальний імпульс","collisionMode":"Змоделюйте зіткнення","mass1":"Об’єкт 1 мас","mass2":"Об'єкт 2 мас","massUnit":"Одиниця маси","kilograms":"Кілограми (кг)","grams":"Грами (г)","tonnes":"Метричні тонни (т)","velocity1":"Початкова швидкість об'єкта 1","velocity2":"Початкова швидкість об'єкта 2","speedUnit":"Одиниця вимірювання швидкості","metersPerSecond":"Метри за секунду (м/с)","kilometersPerHour":"Кілометрів на годину (км/год)","feetPerSecond":"Футів на секунду (футів/с)","restitution":"Коефіцієнт реституції (0–1)","accuracyNote":"Одномірна класична модель. \nПозитивні та негативні швидкості показують напрямок. \nЗіткнення розглядаються як ізольовані: зовнішні імпульси, обертання, деталі деформації чи релятивістські ефекти не моделюються. \nЗначення 1 означає ідеальну еластичність; \n0 є абсолютно нееластичним. \nЦе освітня оцінка, а не інженерна оцінка чи оцінка безпеки."},"actions":{"calculate":"Обчисли","reset":"Очистити","copy":"Результат копіювання","example":"Спробуйте зіткнутися рівні маси","result":"Результат імпульсу"},"messages":{"calculated":"Розрахунок готовий.","checkInputs":"Введіть дві позитивні маси, дійсні швидкості зі знаком, підтримувані одиниці та відновлене значення від 0 до 1.","momentumBefore":"Загальний імпульс перед зіткненням","kineticEnergyBefore":"Загальна кінетична енергія до зіткнення","finalVelocity1":"Кінцева швидкість об'єкта 1","finalVelocity2":"Кінцева швидкість об'єкта 2","momentumAfter":"Загальний імпульс після зіткнення","kineticEnergyAfter":"Повна кінетична енергія після зіткнення","energyLoss":"Кінетична енергія, перетворена або втрачена в моделі"},"additionalFaqs":[{"question":"Що означає негативна швидкість?","answer":"Це означає, що об’єкт рухається в протилежному напрямку від вибраного позитивного напрямку. \nЗберігайте знак при введенні обох швидкостей; \nце впливає на загальний імпульс і результат зіткнення."},{"question":"Що означає коефіцієнт реституції?","answer":"Він описує відносну швидкість відриву після одновимірного удару порівняно зі швидкістю наближення. \nНуль моделює ідеально непружне зіткнення; \nодин моделює ідеальне пружне зіткнення. \nСправжні матеріали можуть змінюватися залежно від умов удару."},{"question":"Чи зберігається імпульс при кожному зіткненні?","answer":"Загальний імпульс зберігається в цій моделі, коли система з двох об’єктів не має чистого зовнішнього імпульсу. \nКалькулятор показує значення до і після, щоб ви могли їх порівняти."},{"question":"Чи охоплює цей калькулятор зіткнення під кутом чи обертання?","answer":"Ні. Моделює рух лише по одній прямій. \nВін не обчислює кути, обертання, форму об’єкта, звук, теплові деталі чи деформацію."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"sw":{"copyLanguage":"sw","name":"Kikokotoo cha Momentum","title":"Kikokotoo cha Momentum Bila Malipo | UsefulVerse","description":"Kokotoa kasi ya mwelekeo mmoja au kielelezo cha mgongano wa vitu viwili na kasi zilizotiwa sahihi. \nBure na ya ndani.","intro":"Pata jumla ya kasi ya vitu viwili vinavyotembea kwenye mstari mmoja, au kadiria kasi yao baada ya mgongano. \nWeka kila mwelekeo kwa kasi chanya au hasi na uchague mgawo wa kurejesha kutoka 0 hadi 1.","howQuestion":"Je, unahesabuje kasi na kasi ya mgongano?","howAnswer":"Kasi ni kasi ya mara nyingi, p = mv, na jumla ni jumla iliyotiwa saini kwa vitu vyote viwili. \nKwa mgongano wa sura moja, kikokotoo hiki hutumia mgawo wa kurejesha kukadiria kila kasi ya mwisho. \nKwa mfano, misa sawa ya kilo 1 inayohamia kwa +2 m/s na -1 m/s kasi ya kubadilishana katika mgongano bora wa elastic, wakati kasi ya jumla inabaki 1 kg·m/s.","privacyQuestion":"Je, thamani zangu zimepakiwa?","privacyAnswer":"No. Hesabu inaendeshwa katika kivinjari hiki; \nmaadili hayajapakiwa au kuhifadhiwa.","fields":{"mode":"Hesabu","momentumMode":"Jumla ya kasi tu","collisionMode":"Mfano wa mgongano","mass1":"Kitu 1 wingi","mass2":"Kitu 2 wingi","massUnit":"Kitengo cha Misa","kilograms":"Kilo (kg)\n\nGramu","grams":"(g)","tonnes":"Tani za kipimo (t)","velocity1":"Kitu 1 kasi ya awali","velocity2":"Kitu 2 kasi ya awali","speedUnit":"Kitengo cha kasi","metersPerSecond":"Mita kwa sekunde (m/s)","kilometersPerHour":"Kilomita kwa saa (km/h)","feetPerSecond":"Futi kwa sekunde (ft/s)","restitution":"Mgawo wa kurejesha (0–1)","accuracyNote":"Mfano wa classical wa mwelekeo mmoja. \nKasi chanya na hasi huonyesha mwelekeo. \nMigongano inachukuliwa kuwa ya pekee: hakuna msukumo wa nje, mzunguko, maelezo ya deformation au athari za relativitiki zinazotolewa. \nThamani ya 1 ni elastic bora; \n0 ni inelastic kikamilifu. \nHili ni kadirio la kielimu, si tathmini ya uhandisi au usalama."},"actions":{"calculate":"Hesabu","reset":"Wazi","copy":"Nakili matokeo","example":"Jaribu misa sawa kugongana","result":"Matokeo ya kasi"},"messages":{"calculated":"Hesabu tayari.","checkInputs":"Weka makundi mawili chanya, kasi halali zilizotiwa saini, vitengo vinavyotumika na thamani ya kurejesha kutoka 0 hadi 1.","momentumBefore":"Kasi kamili kabla ya mgongano","kineticEnergyBefore":"Jumla ya nishati ya kinetiki kabla ya mgongano","finalVelocity1":"Kitu 1 kasi ya mwisho","finalVelocity2":"Kitu 2 kasi ya mwisho","momentumAfter":"Kasi kamili baada ya mgongano","kineticEnergyAfter":"Jumla ya nishati ya kinetiki baada ya mgongano","energyLoss":"Nishati ya kinetic iliyobadilishwa au kupotea katika mfano"},"additionalFaqs":[{"question":"Kasi hasi inamaanisha nini?","answer":"Inamaanisha kuwa kitu kinasonga kinyume na mwelekeo mzuri uliochagua. \nWeka ishara wakati wa kuingia kasi zote mbili; \ninathiri kasi ya jumla na matokeo ya mgongano."},{"question":"Je, mgawo wa kurejesha unamaanisha nini?","answer":"Inaelezea kasi ya jamaa ya kutenganisha baada ya athari ya mwelekeo mmoja ikilinganishwa na kasi inayokaribia. \nMifano ya sifuri mgongano wa inelastic kikamilifu; \nmoja ya mifano ya mgongano bora wa elastic. \nNyenzo halisi zinaweza kutofautiana kulingana na hali ya athari."},{"question":"Je, kasi huhifadhiwa katika kila mgongano?","answer":"Kasi kamili huhifadhiwa katika modeli hii wakati mfumo wa vitu viwili hauna msukumo wa nje. \nKikokotoo kinaonyesha thamani kabla na baada ili uweze kuzilinganisha."},{"question":"Je, kikokotoo hiki kinafunika migongano ya pembe au inayozunguka?","answer":"Hapana. Ni mfano wa mwendo kwenye mstari mmoja ulionyooka pekee. \nHaihesabu pembe, mzunguko, sura ya kitu, sauti, maelezo ya joto au deformation."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"mr":{"copyLanguage":"mr","name":"मोमेंटम कॅल्क्युलेटर","title":"मोमेंटम कॅल्क्युलेटर मोफत | UsefulVerse","description":"एक-आयामी गतीची गणना करा किंवा स्वाक्षरी केलेल्या गतीसह दोन-ऑब्जेक्ट टक्कर मॉडेल करा. \nमोफत आणि स्थानिक.","intro":"एका रेषेने फिरणाऱ्या दोन वस्तूंसाठी एकूण गती शोधा किंवा टक्कर झाल्यानंतर त्यांच्या गतीचा अंदाज लावा. \nप्रत्येक दिशा सकारात्मक किंवा नकारात्मक वेगासह सेट करा आणि 0 ते 1 पर्यंत परतावा गुणांक निवडा.","howQuestion":"तुम्ही संवेग आणि टक्कर गती कशी मोजता?","howAnswer":"संवेग म्हणजे वस्तुमान गुणाकार वेग, p = mv, आणि एकूण दोन्ही वस्तूंसाठी चिन्हांकित बेरीज आहे. \nएका-आयामी टक्करसाठी, हे कॅल्क्युलेटर प्रत्येक अंतिम वेगाचा अंदाज घेण्यासाठी पुनर्संचयन गुणांक वापरतो. \nउदाहरणार्थ, आदर्श लवचिक टक्करमध्ये +2 m/s आणि −1 m/s विनिमय गतीने हलणारे समान 1 kg वस्तुमान, तर एकूण गती 1 kg·m/s राहते.","privacyQuestion":"माझी मूल्ये अपलोड केली आहेत का?","privacyAnswer":"क्र. गणना या ब्राउझरमध्ये चालते; \nमूल्ये अपलोड किंवा जतन केलेली नाहीत.","fields":{"mode":"गणना","momentumMode":"एकूण गती फक्त","collisionMode":"मॉडेल टक्कर","mass1":"ऑब्जेक्ट 1 वस्तुमान","mass2":"ऑब्जेक्ट 2 वस्तुमान","massUnit":"वस्तुमान युनिट","kilograms":"किलोग्राम (किलो)","grams":"ग्रॅम (ग्रॅम)\n\n६५४३२१००१६१२३४५६ मेट्रिक टन (टी)","tonnes":"Metric tonnes (t)","velocity1":"ऑब्जेक्ट 1 प्रारंभिक वेग","velocity2":"ऑब्जेक्ट 2 प्रारंभिक वेग","speedUnit":"वेग युनिट","metersPerSecond":"मीटर प्रति सेकंद (मी/से)","kilometersPerHour":"किलोमीटर प्रति तास (किमी/ता)","feetPerSecond":"फूट प्रति सेकंद (फूट/से)","restitution":"परतावा गुणांक (0–1)","accuracyNote":"एक-आयामी शास्त्रीय मॉडेल. \nसकारात्मक आणि नकारात्मक वेग दिशा दाखवतात. \nटक्करांना वेगळे मानले जाते: कोणतेही बाह्य आवेग, रोटेशन, विकृती तपशील किंवा सापेक्ष प्रभाव मॉडेल केलेले नाहीत. \n1 चे मूल्य आदर्श लवचिक आहे; \n0 पूर्णपणे लवचिक आहे. \nहा एक शैक्षणिक अंदाज आहे, अभियांत्रिकी किंवा सुरक्षितता मूल्यांकन नाही."},"actions":{"calculate":"गणना करा","reset":"साफ करा","copy":"निकाल कॉपी करा","example":"समान वस्तुमान टक्कर करून पहा","result":"मोमेंटम निकाल"},"messages":{"calculated":"गणना तयार आहे.","checkInputs":"दोन धनात्मक वस्तुमान, वैध स्वाक्षरी वेग, समर्थित एकके आणि 0 ते 1 पर्यंत पुनर्स्थापना मूल्य प्रविष्ट करा.","momentumBefore":"टक्करपूर्वी एकूण गती","kineticEnergyBefore":"टक्कर होण्यापूर्वी एकूण गतीज ऊर्जा","finalVelocity1":"ऑब्जेक्ट 1 अंतिम वेग","finalVelocity2":"ऑब्जेक्ट 2 अंतिम वेग","momentumAfter":"टक्कर नंतर एकूण गती","kineticEnergyAfter":"टक्कर नंतर एकूण गतीज ऊर्जा","energyLoss":"मॉडेलमध्ये गतिज ऊर्जा रूपांतरित किंवा गमावली"},"additionalFaqs":[{"question":"ऋण वेग म्हणजे काय?","answer":"याचा अर्थ ऑब्जेक्ट तुम्ही निवडलेल्या सकारात्मक दिशेपासून विरुद्ध दिशेने सरकतो. \nदोन्ही वेगात प्रवेश करताना चिन्ह ठेवा; \nहे एकूण गती आणि टक्कर परिणाम प्रभावित करते."},{"question":"परतावा गुणांक म्हणजे काय?","answer":"हे जवळ येणा-या वेगाच्या तुलनेत एका-आयामी प्रभावानंतर सापेक्ष विभक्त गतीचे वर्णन करते. \nशून्य मॉडेल एक उत्तम प्रकारे लवचिक टक्कर; \nएक मॉडेल एक आदर्श लवचिक टक्कर. \nवास्तविक सामग्री प्रभाव परिस्थितीनुसार बदलू शकते."},{"question":"प्रत्येक टक्केमध्ये संवेग जतन केला जातो का?","answer":"या मॉडेलमध्ये एकूण गती संरक्षित केली जाते जेव्हा दोन-ऑब्जेक्ट सिस्टममध्ये निव्वळ बाह्य आवेग नसते. \nकॅल्क्युलेटर आधी आणि नंतरची मूल्ये दाखवतो जेणेकरून तुम्ही त्यांची तुलना करू शकता."},{"question":"हे कॅल्क्युलेटर कोन किंवा फिरणारी टक्कर कव्हर करते का?","answer":"क्र. हे फक्त एका सरळ रेषेवर गतीचे मॉडेल करते. \nहे कोन, रोटेशन, ऑब्जेक्टचा आकार, आवाज, उष्णता तपशील किंवा विकृती मोजत नाही."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"te":{"copyLanguage":"te","name":"మొమెంటం కాలిక్యులేటర్","title":"మొమెంటం కాలిక్యులేటర్ ఉచితం | UsefulVerse","description":"ఒక డైమెన్షనల్ మొమెంటంను లెక్కించండి లేదా సంతకం చేసిన వేగంతో రెండు-వస్తువుల తాకిడిని మోడల్ చేయండి. \nఉచిత మరియు స్థానిక.","intro":"ఒక రేఖ వెంట కదులుతున్న రెండు వస్తువుల కోసం మొత్తం మొమెంటంను కనుగొనండి లేదా ఢీకొన్న తర్వాత వాటి వేగాన్ని అంచనా వేయండి. \nప్రతి దిశను సానుకూల లేదా ప్రతికూల వేగంతో సెట్ చేయండి మరియు 0 నుండి 1 వరకు పునరుద్ధరణ యొక్క గుణకాన్ని ఎంచుకోండి.","howQuestion":"మీరు మొమెంటం మరియు తాకిడి వేగాన్ని ఎలా గణిస్తారు?","howAnswer":"మొమెంటం అనేది ద్రవ్యరాశి సమయాల వేగం, p = mv మరియు మొత్తం రెండు వస్తువులకు సంతకం చేసిన మొత్తం. \nఒక డైమెన్షనల్ తాకిడి కోసం, ఈ కాలిక్యులేటర్ ప్రతి తుది వేగాన్ని అంచనా వేయడానికి పునరుద్ధరణ గుణకాన్ని ఉపయోగిస్తుంది. \nఉదాహరణకు, ఆదర్శ సాగే తాకిడిలో +2 m/s మరియు −1 m/s మార్పిడి వేగంతో సమానమైన 1 kg ద్రవ్యరాశి, మొత్తం మొమెంటం 1 kg·m/s ఉంటుంది.","privacyQuestion":"నా విలువలు అప్‌లోడ్ చేయబడ్డాయా?","privacyAnswer":"నం. ఈ బ్రౌజర్‌లో గణన నడుస్తుంది; \nవిలువలు అప్‌లోడ్ చేయబడవు లేదా సేవ్ చేయబడవు.","fields":{"mode":"గణన","momentumMode":"మొత్తం మొమెంటం మాత్రమే","collisionMode":"మోడల్ ఒక ఘర్షణ","mass1":"వస్తువు 1 ద్రవ్యరాశి","mass2":"వస్తువు 2 ద్రవ్యరాశి","massUnit":"మాస్ యూనిట్","kilograms":"కిలోగ్రాములు (కిలోలు)","grams":"గ్రాములు (గ్రా)","tonnes":"మెట్రిక్ టన్నులు (టి)","velocity1":"ఆబ్జెక్ట్ 1 ప్రారంభ వేగం","velocity2":"ఆబ్జెక్ట్ 2 ప్రారంభ వేగం","speedUnit":"వెలాసిటీ యూనిట్\n\nసెకనుకు","metersPerSecond":"మీటర్లు (మీ/సె)","kilometersPerHour":"గంటకు కిలోమీటర్లు (కిమీ/గం)\n\nసెకనుకు","feetPerSecond":"అడుగులు (అడుగు/సె)","restitution":"పునరుద్ధరణ గుణకం (0–1)","accuracyNote":"వన్-డైమెన్షనల్ క్లాసికల్ మోడల్. \nసానుకూల మరియు ప్రతికూల వేగాలు దిశను చూపుతాయి. \nఢీకొన్నవి వివిక్తమైనవిగా పరిగణించబడతాయి: బాహ్య ప్రేరణ, భ్రమణం, వైకల్య వివరాలు లేదా సాపేక్ష ప్రభావాలు రూపొందించబడవు. \n1 విలువ ఆదర్శవంతమైన సాగేది; \n0 ఖచ్చితంగా అస్థిరమైనది. \nఇది విద్యాపరమైన అంచనా, ఇంజనీరింగ్ లేదా భద్రతా అంచనా కాదు."},"actions":{"calculate":"లెక్కించండి","reset":"క్లియర్","copy":"ఫలితాన్ని కాపీ చేయండి","example":"సమాన ద్రవ్యరాశిని ఢీకొట్టడానికి ప్రయత్నించండి","result":"మొమెంటం ఫలితం"},"messages":{"calculated":"గణన సిద్ధంగా ఉంది.","checkInputs":"రెండు సానుకూల ద్రవ్యరాశులు, చెల్లుబాటు అయ్యే సంతకం చేసిన వేగాలు, మద్దతు ఉన్న యూనిట్లు మరియు 0 నుండి 1కి తిరిగి వచ్చే విలువను నమోదు చేయండి.","momentumBefore":"ఢీకొనడానికి ముందు మొత్తం మొమెంటం","kineticEnergyBefore":"ఢీకొనడానికి ముందు మొత్తం గతి శక్తి","finalVelocity1":"ఆబ్జెక్ట్ 1 చివరి వేగం","finalVelocity2":"ఆబ్జెక్ట్ 2 చివరి వేగం","momentumAfter":"ఢీకొన్న తర్వాత మొత్తం మొమెంటం","kineticEnergyAfter":"ఢీకొన్న తర్వాత మొత్తం గతి శక్తి","energyLoss":"మోడల్‌లో గతి శక్తి మార్చబడింది లేదా కోల్పోయింది"},"additionalFaqs":[{"question":"ప్రతికూల వేగం అంటే ఏమిటి?","answer":"అంటే మీరు ఎంచుకున్న సానుకూల దిశ నుండి వస్తువు వ్యతిరేక దిశలో కదులుతుంది. \nరెండు వేగాలను నమోదు చేసేటప్పుడు గుర్తును ఉంచండి; \nఇది మొత్తం మొమెంటం మరియు తాకిడి ఫలితాన్ని ప్రభావితం చేస్తుంది."},{"question":"పునరుద్ధరణ గుణకం అంటే ఏమిటి?","answer":"ఇది సమీపించే వేగంతో పోలిస్తే ఒక డైమెన్షనల్ ప్రభావం తర్వాత సాపేక్షంగా వేరుచేసే వేగాన్ని వివరిస్తుంది. \nజీరో మోడల్స్ సంపూర్ణ అస్థిర తాకిడి; \nఒక ఆదర్శవంతమైన సాగే తాకిడిని మోడల్ చేస్తుంది. \nప్రభావ పరిస్థితులతో నిజమైన పదార్థాలు మారవచ్చు."},{"question":"ప్రతి తాకిడిలో మొమెంటం సంరక్షించబడుతుందా?","answer":"రెండు-ఆబ్జెక్ట్ సిస్టమ్‌కు నికర బాహ్య ప్రేరణ లేనప్పుడు మొత్తం మొమెంటం ఈ మోడల్‌లో భద్రపరచబడుతుంది. \nకాలిక్యులేటర్ ముందు మరియు తరువాత విలువలను చూపుతుంది కాబట్టి మీరు వాటిని పోల్చవచ్చు."},{"question":"ఈ కాలిక్యులేటర్ కోణీయ లేదా తిరిగే ఘర్షణలను కవర్ చేస్తుందా?","answer":"నం. ఇది ఒక సరళ రేఖపై మాత్రమే చలనాన్ని మోడల్ చేస్తుంది. \nఇది కోణాలు, భ్రమణం, వస్తువు ఆకారం, ధ్వని, ఉష్ణ వివరాలు లేదా వైకల్యాన్ని లెక్కించదు."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ha":{"copyLanguage":"ha","name":"Kalkuleta na Momentum","title":"Kalkuleta Momentum Kyauta | UsefulVerse","description":"Yi ƙididdige saurin girma ɗaya ko ƙirar karo abu biyu tare da sa hannu kan saurin gudu. \nKyauta da na gida.","intro":"Nemo jimlar ƙarfin abubuwa biyu masu motsi tare da layi ɗaya, ko kimanta saurinsu bayan karo. \nSaita kowane jagora tare da ingantacciyar gudu ko mara kyau kuma zaɓi adadin maidowa daga 0 zuwa 1.","howQuestion":"Ta yaya kuke lissafta saurin gudu da karo?","howAnswer":"Matsakaicin saurin lokutan taro ne, p = mv, kuma jimlar ita ce jimlar sa hannu na abubuwa biyu. \nDon karo mai girma ɗaya, wannan kalkuleta yana amfani da ƙididdiga na ramawa don ƙididdige kowane gudu na ƙarshe. \nMisali, daidai gwargwado 1 kg talakawa masu motsi a +2 m/s da -1 m/s musanya saurin gudu a madaidaicin karo na roba, yayin da jimlar ƙarfin ya kasance 1 kg·m/s.","privacyQuestion":"An loda kimara?","privacyAnswer":"A'a. Lissafin yana gudana a cikin wannan browser; \nba a ɗora darajar ko adana su ba.","fields":{"mode":"Lissafi","momentumMode":"Jimlar ƙarfin ƙarfi kawai","collisionMode":"Samfuran karo","mass1":"Abu 1 taro","mass2":"Abu 2 taro","massUnit":"Mass unit","kilograms":"Kilogram (kg)","grams":"Grams (g)","tonnes":"Metric tonne (t)","velocity1":"Abu 1 saurin farko","velocity2":"Abu 2 saurin farko","speedUnit":"Naúrar Sauri","metersPerSecond":"Mita a sakan daya (m/s)","kilometersPerHour":"Kilomita a kowace awa (km/h)","feetPerSecond":"Kafa a sakan daya (ft/s)","restitution":"Adadin ramawa (0-1)","accuracyNote":"Tsarin gargajiya mai girma ɗaya. \nKyawawan hanyoyi masu kyau da mara kyau suna nuna alkibla. \nAna kula da haɗuwa kamar yadda aka keɓe: babu wani motsi na waje, juyawa, dalla-dalla na lalacewa ko tasirin alaƙa da aka tsara. \nƘimar 1 shine manufa na roba; \n0 ba shi da kyau. \nWannan ƙididdigewa ce ta ilimi, ba aikin injiniya ko ƙimar aminci ba."},"actions":{"calculate":"Lissafi","reset":"Bayyana","copy":"Kwafi sakamakon","example":"Gwada daidai gwargwado suna karo","result":"Sakamakon Moment"},"messages":{"calculated":"An shirya lissafin.","checkInputs":"Shigar da taro masu inganci guda biyu, ingantattun saurin sa hannu, raka'o'i masu tallafi, da ƙimar mayarwa daga 0 zuwa 1.","momentumBefore":"Jimlar yawan kuzarin kafin karo","kineticEnergyBefore":"Jimlar kuzarin motsa jiki kafin karo","finalVelocity1":"Abu 1 gudun karshe","finalVelocity2":"Abu 2 gudun karshe","momentumAfter":"Jimillar tashin hankali bayan karo","kineticEnergyAfter":"Jimlar kuzarin motsa jiki bayan karo","energyLoss":"Kinetic makamashi tuba ko rasa a cikin samfurin"},"additionalFaqs":[{"question":"Menene ma'anar mummunan gudu?","answer":"Yana nufin abu yana motsawa zuwa kishiyar hanya daga ingantacciyar hanyar da kuka zaɓa. \nAjiye alamar lokacin shigar da sauri biyu; \nyana shafar jimlar ƙarko da sakamakon karo."},{"question":"Menene ma'anar ma'anar ramawa?","answer":"Yana bayyana saurin rabuwar dangi bayan tasiri mai girma ɗaya idan aka kwatanta da saurin gabatowa. \nSifili model wani daidai inelastic karo; \ndaya model wani manufa na roba karo. \nKayan gaske na iya bambanta tare da yanayin tasiri."},{"question":"An kiyaye saurin gudu a kowane karo?","answer":"An kiyaye jimlar ƙarfin ƙarfi a cikin wannan ƙirar lokacin da tsarin abu biyu ba shi da wani buri na waje. \nKalkuleta yana nuna ƙima kafin da bayan haka zaka iya kwatanta su."},{"question":"Shin wannan kalkuleta yana rufe karo na kusurwa ko juyawa?","answer":"A'a. Yana ƙirar motsi akan layi madaidaiciya ɗaya kawai. \nBa ya lissafin kusurwoyi, juyawa, siffar abu, sauti, cikakkun bayanai na zafi ko nakasawa."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"tl":{"copyLanguage":"tl","name":"Momentum Calculator","title":"Momentum Calculator Libre | UsefulVerse","description":"Kalkulahin ang one-dimensional na momentum o magmodelo ng dalawang bagay na banggaan na may signed na bilis. \nLibre at lokal.","intro":"Maghanap ng kabuuang momentum para sa dalawang bagay na gumagalaw sa isang linya, o tantiyahin ang mga bilis ng mga ito pagkatapos ng banggaan. \nItakda ang bawat direksyon na may positibo o negatibong bilis at pumili ng koepisyent ng pagsasauli mula 0 hanggang 1.","howQuestion":"Paano mo kinakalkula ang momentum at bilis ng banggaan?","howAnswer":"Ang momentum ay mass times velocity, p = mv, at ang kabuuan ay ang signed sum para sa parehong bagay. \nPara sa isang one-dimensional na banggaan, ginagamit ng calculator na ito ang coefficient of restitution upang tantyahin ang bawat final velocity. \nHalimbawa, katumbas ng 1 kg na masa na gumagalaw sa +2 m/s at −1 m/s na bilis ng palitan sa isang perpektong nababanat na banggaan, habang ang kabuuang momentum ay nananatiling 1 kg·m/s.","privacyQuestion":"Na-upload ba ang aking mga halaga?","privacyAnswer":"Hindi. Ang pagkalkula ay tumatakbo sa browser na ito; \nang mga halaga ay hindi na-upload o nai-save.","fields":{"mode":"Pagkalkula","momentumMode":"Kabuuang momentum lang","collisionMode":"Magmodelo ng banggaan","mass1":"Object 1 mass","mass2":"Object 2 mass","massUnit":"Yunit ng masa","kilograms":"Mga Kilogramo (kg)","grams":"Gram (g)","tonnes":"Sukatan tonelada (t)","velocity1":"Object 1 inisyal na bilis","velocity2":"Object 2 inisyal na bilis","speedUnit":"Yunit ng bilis","metersPerSecond":"Mga metro bawat segundo (m/s)","kilometersPerHour":"Kilometro bawat oras (km/h)","feetPerSecond":"Talampakan bawat segundo (ft/s)","restitution":"Coefficient of restitution (0–1)","accuracyNote":"Isang-dimensional na klasikal na modelo. \nAng mga positibo at negatibong bilis ay nagpapakita ng direksyon. \nAng mga banggaan ay itinuturing na nakahiwalay: walang panlabas na salpok, pag-ikot, detalye ng deformation o relativistic na epekto ang namodelo. \nAng halaga ng 1 ay perpektong nababanat; \n0 ay ganap na hindi nababanat. \nIto ay isang pang-edukasyon na pagtatantya, hindi isang engineering o kaligtasan na pagtatasa."},"actions":{"calculate":"Kalkulahin","reset":"Maaliwalas","copy":"Kopyahin ang resulta","example":"Subukan ang pantay na masa na nagbabanggaan","result":"Resulta ng momentum"},"messages":{"calculated":"Handa na ang pagkalkula.","checkInputs":"Maglagay ng dalawang positibong masa, valid signed velocities, supported units, at isang restitution value mula 0 hanggang 1.","momentumBefore":"Kabuuang momentum bago ang banggaan","kineticEnergyBefore":"Kabuuang kinetic energy bago ang banggaan","finalVelocity1":"Object 1 final velocity","finalVelocity2":"Object 2 final velocity","momentumAfter":"Kabuuang momentum pagkatapos ng banggaan","kineticEnergyAfter":"Kabuuang kinetic energy pagkatapos ng banggaan","energyLoss":"Kinetic energy na na-convert o nawala sa modelo"},"additionalFaqs":[{"question":"Ano ang ibig sabihin ng negatibong tulin?","answer":"Nangangahulugan ito na ang bagay ay gumagalaw sa tapat na direksyon mula sa positibong direksyon na iyong pinili. \nPanatilihin ang tanda kapag pumapasok sa parehong bilis; \nnaaapektuhan nito ang kabuuang momentum at ang resulta ng banggaan."},{"question":"Ano ang ibig sabihin ng coefficient of restitution?","answer":"Inilalarawan nito ang relatibong bilis ng paghihiwalay pagkatapos ng one-dimensional na epekto kumpara sa paparating na bilis. \nZero modelo ng isang perpektong hindi nababanat na banggaan; \nang isa ay nagmomodelo ng perpektong nababanat na banggaan. \nAng mga tunay na materyales ay maaaring mag-iba sa mga kondisyon ng epekto."},{"question":"Napanatili ba ang momentum sa bawat banggaan?","answer":"Ang kabuuang momentum ay pinananatili sa modelong ito kapag ang dalawang-bagay na sistema ay walang netong panlabas na salpok. \nAng calculator ay nagpapakita ng mga halaga bago at pagkatapos upang maihambing mo ang mga ito."},{"question":"Sinasaklaw ba ng calculator na ito ang mga anggulo o umiikot na banggaan?","answer":"Hindi. Nagmomodelo ito ng paggalaw sa isang tuwid na linya lamang. \nHindi nito kinakalkula ang mga anggulo, pag-ikot, hugis ng bagay, tunog, mga detalye ng init o pagpapapangit."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ta":{"copyLanguage":"ta","name":"உந்த கால்குலேட்டர்","title":"உந்த கால்குலேட்டர் இலவசம் | UsefulVerse","description":"ஒரு பரிமாண வேகத்தைக் கணக்கிடுங்கள் அல்லது கையொப்பமிடப்பட்ட வேகத்துடன் இரு பொருள் மோதலை மாதிரியாக்குங்கள். \nஇலவசம் மற்றும் உள்ளூர்.","intro":"ஒரு கோட்டில் நகரும் இரண்டு பொருட்களின் மொத்த வேகத்தைக் கண்டறியவும் அல்லது மோதலுக்குப் பிறகு அவற்றின் வேகத்தை மதிப்பிடவும். \nஒவ்வொரு திசையையும் நேர்மறை அல்லது எதிர்மறை திசைவேகத்துடன் அமைத்து, 0 முதல் 1 வரையிலான மறுசீரமைப்பின் குணகத்தைத் தேர்ந்தெடுக்கவும்.","howQuestion":"உந்தம் மற்றும் மோதல் வேகத்தை எவ்வாறு கணக்கிடுவது?","howAnswer":"உந்தம் என்பது வெகுஜன நேர வேகம், p = mv, மற்றும் மொத்தமானது இரண்டு பொருள்களுக்கும் கையொப்பமிடப்பட்ட தொகையாகும். \nஒரு பரிமாண மோதலுக்கு, இந்த கால்குலேட்டர் ஒவ்வொரு இறுதி வேகத்தையும் மதிப்பிடுவதற்கு மீட்டெடுப்பின் குணகத்தைப் பயன்படுத்துகிறது. \nஎடுத்துக்காட்டாக, ஒரு சிறந்த மீள் மோதலில் +2 m/s மற்றும் −1 m/s பரிமாற்ற வேகத்தில் நகரும் சமமான 1 கிலோ நிறைகள், மொத்த வேகம் 1 kg·m/s ஆக இருக்கும்.","privacyQuestion":"எனது மதிப்புகள் பதிவேற்றப்பட்டதா?","privacyAnswer":"எண். கணக்கீடு இந்த உலாவியில் இயங்குகிறது; \nமதிப்புகள் பதிவேற்றப்படவில்லை அல்லது சேமிக்கப்படவில்லை.","fields":{"mode":"கணக்கீடு","momentumMode":"மொத்த வேகம் மட்டும்","collisionMode":"ஒரு மோதல் மாதிரி","mass1":"பொருள் 1 நிறை","mass2":"பொருள் 2 நிறை","massUnit":"மாஸ் யூனிட்","kilograms":"கிலோகிராம் (கிலோ)","grams":"கிராம் (கிராம்)","tonnes":"மெட்ரிக் டன்கள் (t)","velocity1":"பொருள் 1 ஆரம்ப வேகம்","velocity2":"பொருள் 2 ஆரம்ப வேகம்","speedUnit":"வேக அலகு","metersPerSecond":"வினாடிக்கு மீட்டர் (மீ/வி)","kilometersPerHour":"ஒரு மணி நேரத்திற்கு கிலோமீட்டர்கள் (கிமீ/ம)","feetPerSecond":"வினாடிக்கு அடி (அடி/வி)","restitution":"மறுசீரமைப்பு குணகம் (0–1)","accuracyNote":"ஒரு பரிமாண கிளாசிக்கல் மாதிரி. \nநேர்மறை மற்றும் எதிர்மறை திசைவேகங்கள் திசையைக் காட்டுகின்றன. \nமோதல்கள் தனிமைப்படுத்தப்பட்டதாகக் கருதப்படுகின்றன: வெளிப்புற தூண்டுதல், சுழற்சி, சிதைவு விவரம் அல்லது சார்பியல் விளைவுகள் மாதிரியாக இல்லை. \n1 இன் மதிப்பு சிறந்த மீள்தன்மையாகும்; \n0 என்பது முற்றிலும் உறுதியற்றது. \nஇது ஒரு கல்வி மதிப்பீடு, பொறியியல் அல்லது பாதுகாப்பு மதிப்பீடு அல்ல."},"actions":{"calculate":"கணக்கிடவும்","reset":"தெளிவு","copy":"முடிவை நகலெடுக்கவும்","example":"சம நிறைகளை மோத முயற்சிக்கவும்","result":"உந்த முடிவு"},"messages":{"calculated":"கணக்கீடு தயார்.","checkInputs":"இரண்டு நேர்மறை நிறைகள், செல்லுபடியாகும் கையொப்பமிடப்பட்ட வேகங்கள், ஆதரிக்கப்படும் அலகுகள் மற்றும் 0 முதல் 1 வரையிலான மதிப்பை உள்ளிடவும்.","momentumBefore":"மோதலுக்கு முந்தைய மொத்த வேகம்","kineticEnergyBefore":"மோதலுக்கு முன் மொத்த இயக்க ஆற்றல்","finalVelocity1":"பொருள் 1 இறுதி வேகம்","finalVelocity2":"பொருள் 2 இறுதி வேகம்","momentumAfter":"மோதலுக்குப் பிறகு மொத்த வேகம்","kineticEnergyAfter":"மோதலுக்குப் பின் மொத்த இயக்க ஆற்றல்","energyLoss":"மாதிரியில் இயக்க ஆற்றல் மாற்றப்பட்டது அல்லது இழந்தது"},"additionalFaqs":[{"question":"எதிர்மறை வேகம் என்றால் என்ன?","answer":"நீங்கள் தேர்ந்தெடுத்த நேர்மறை திசையிலிருந்து பொருள் எதிர் திசையில் நகர்கிறது. \nஇரண்டு வேகங்களையும் உள்ளிடும்போது அடையாளத்தை வைத்திருங்கள்; \nஇது மொத்த வேகத்தையும் மோதல் முடிவையும் பாதிக்கிறது."},{"question":"மீட்டெடுப்பின் குணகம் எதைக் குறிக்கிறது?","answer":"இது நெருங்கி வரும் வேகத்துடன் ஒப்பிடும்போது ஒரு பரிமாண தாக்கத்திற்குப் பிறகு தொடர்புடைய பிரிக்கும் வேகத்தை விவரிக்கிறது. \nபூஜ்ஜிய மாதிரிகள் ஒரு முழுமையான உறுதியற்ற மோதல்; \nஒரு சிறந்த மீள் மோதலை மாதிரிகள். \nஉண்மையான பொருட்கள் தாக்க நிலைமைகளைப் பொறுத்து மாறுபடும்."},{"question":"ஒவ்வொரு மோதலிலும் உந்தம் பாதுகாக்கப்படுகிறதா?","answer":"இரண்டு-பொருள் அமைப்புக்கு நிகர வெளிப்புற தூண்டுதல் இல்லாதபோது இந்த மாதிரியில் மொத்த வேகம் பாதுகாக்கப்படுகிறது. \nகால்குலேட்டர் முன்னும் பின்னும் மதிப்புகளைக் காட்டுகிறது, எனவே நீங்கள் அவற்றை ஒப்பிடலாம்."},{"question":"இந்த கால்குலேட்டர் கோண அல்லது சுழலும் மோதல்களை மறைக்கிறதா?","answer":"எண். இது ஒரு நேர் கோட்டில் மட்டுமே இயக்கத்தை மாதிரியாக்குகிறது. \nஇது கோணங்கள், சுழற்சி, பொருளின் வடிவம், ஒலி, வெப்ப விவரங்கள் அல்லது சிதைவைக் கணக்கிடாது."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"fa":{"copyLanguage":"fa","name":"ماشین حساب تکانه","title":"Momentum Calculator Free | UsefulVerse","description":"تکانه تک بعدی را محاسبه کنید یا برخورد دو جسم را با سرعت های مشخص مدل کنید. \nرایگان و محلی.","intro":"تکانه کل دو جسم که در امتداد یک خط حرکت می کنند را بیابید یا سرعت آنها را پس از برخورد تخمین بزنید. \nهر جهت را با سرعت مثبت یا منفی تنظیم کنید و ضریب بازگشت را از 0 تا 1 انتخاب کنید.","howQuestion":"چگونه تکانه و سرعت برخورد را محاسبه می کنید؟","howAnswer":"تکانه جرم ضربدر سرعت، p = mv است، و مجموع مجموع علامت برای هر دو جسم است. \nبرای یک برخورد یک بعدی، این ماشین حساب از ضریب بازگشت برای تخمین هر سرعت نهایی استفاده می کند. \nبه عنوان مثال، جرم‌های 1 کیلوگرمی که با سرعت‌های 2+ متر بر ثانیه و 1- متر بر ثانیه حرکت می‌کنند، در یک برخورد الاستیک ایده‌آل تبادل می‌کنند، در حالی که تکانه کل 1 کیلوگرم در متر بر ثانیه باقی می‌ماند.","privacyQuestion":"آیا مقادیر من آپلود شده اند؟","privacyAnswer":"شماره محاسبه در این مرورگر انجام می شود. \nمقادیر آپلود یا ذخیره نمی شوند.","fields":{"mode":"محاسبه","momentumMode":"فقط تکانه کل","collisionMode":"مدل برخورد","mass1":"جرم جسم 1","mass2":"جرم جسم 2","massUnit":"واحد انبوه","kilograms":"کیلوگرم (کیلوگرم)","grams":"گرم (گرم)","tonnes":"متریک تن (t)","velocity1":"سرعت اولیه جسم 1","velocity2":"سرعت اولیه جسم 2","speedUnit":"واحد سرعت","metersPerSecond":"متر بر ثانیه (m/s)","kilometersPerHour":"کیلومتر در ساعت (کیلومتر در ساعت)","feetPerSecond":"فوت بر ثانیه (ft/s)","restitution":"ضریب استرداد (0–1)","accuracyNote":"مدل کلاسیک تک بعدی. \nسرعت های مثبت و منفی جهت را نشان می دهند. \nبرخوردها به صورت ایزوله در نظر گرفته می شوند: هیچ ضربه خارجی، چرخش، جزئیات تغییر شکل یا اثرات نسبیتی مدل سازی نشده است. \nمقدار 1 الاستیک ایده آل است. \n0 کاملا غیر کشسان است. \nاین یک برآورد آموزشی است، نه یک ارزیابی مهندسی یا ایمنی."},"actions":{"calculate":"محاسبه کنید","reset":"پاک کنید","copy":"نتیجه را کپی کنید","example":"برخورد جرم های مساوی را امتحان کنید","result":"نتیجه تکانه"},"messages":{"calculated":"محاسبه آماده است.","checkInputs":"دو جرم مثبت، سرعت‌های علامت‌دار معتبر، واحدهای پشتیبانی‌شده و مقدار بازگردانی را از 0 تا 1 وارد کنید.","momentumBefore":"تکانه کل قبل از برخورد","kineticEnergyBefore":"انرژی جنبشی کل قبل از برخورد","finalVelocity1":"شی 1 سرعت نهایی","finalVelocity2":"شی 2 سرعت نهایی","momentumAfter":"تکانه کل پس از برخورد","kineticEnergyAfter":"انرژی جنبشی کل پس از برخورد","energyLoss":"انرژی جنبشی تبدیل شده یا از دست رفته در مدل"},"additionalFaqs":[{"question":"سرعت منفی به چه معناست؟","answer":"یعنی جسم در جهت مخالف جهت مثبتی که شما انتخاب کرده اید حرکت می کند. \nهنگام وارد کردن هر دو سرعت علامت را نگه دارید. \nاین تکانه کل و نتیجه برخورد را تحت تاثیر قرار می دهد."},{"question":"ضریب استرداد یعنی چه؟","answer":"سرعت جداسازی نسبی را پس از یک ضربه تک بعدی در مقایسه با سرعت نزدیک توصیف می کند. \nمدل های صفر یک برخورد کاملا غیر کشسان. \nیکی یک برخورد الاستیک ایده آل را مدل می کند. \nمواد واقعی می توانند با شرایط ضربه متفاوت باشند."},{"question":"آیا تکانه در هر برخورد حفظ می شود؟","answer":"تکانه کل در این مدل زمانی حفظ می شود که سیستم دو شیء هیچ ضربه خارجی خالص نداشته باشد. \nماشین حساب مقادیر قبل و بعد را نشان می دهد تا بتوانید آنها را با هم مقایسه کنید."},{"question":"آیا این ماشین حساب برخوردهای زاویه دار یا چرخشی را پوشش می دهد؟","answer":"نه. این حرکت را فقط در یک خط مستقیم مدل می کند. \nزوایا، چرخش، شکل جسم، صدا، جزئیات گرمایی یا تغییر شکل را محاسبه نمی کند."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"am":{"copyLanguage":"am","name":"ሞመንተም ማስያ","title":"ሞመንተም ካልኩሌተር ነፃ | UsefulVerse","description":"አንድ-ልኬት ሞመንተም አስሉ ወይም ባለሁለት ነገር ግጭት ከተፈረመ ፍጥነት ጋር ሞዴል ያድርጉ። \nነፃ እና አካባቢያዊ።","intro":"በአንድ መስመር ላይ ለሚንቀሳቀሱ ሁለት ነገሮች አጠቃላይ ፍጥነትን ይፈልጉ ወይም ከግጭት በኋላ ፍጥነታቸውን ይገምቱ። \nእያንዳንዱን አቅጣጫ በአዎንታዊ ወይም አሉታዊ ፍጥነት ያቀናብሩ እና ከ 0 ወደ 1 የመመለሻ ብዛት ይምረጡ።","howQuestion":"የፍጥነት እና የግጭት ፍጥነትን እንዴት ማስላት ይቻላል?","howAnswer":"ሞመንተም የጅምላ ጊዜ ፍጥነት ነው፣ p = mv፣ እና አጠቃላይ የሁለቱም ነገሮች የተፈረመ ድምር ነው። \nለአንድ-ልኬት ግጭት፣ ይህ ካልኩሌተር እያንዳንዱን የመጨረሻ ፍጥነት ለመገመት የመልሶ ማቋቋም ቅንጅትን ይጠቀማል። \nለምሳሌ፣ እኩል የሆነ 1 ኪ.ግ ክብደት በ +2 ሜ/ሰ እና -1 ሜትር/ሰ የሚንቀሳቀስ የፍጥነት ልውውጥ በተመጣጣኝ የመለጠጥ ግጭት ውስጥ ሲሆን አጠቃላይ ፍጥነቱ 1 ኪሎ ሜትር በሰከንድ ይቀራል።","privacyQuestion":"እሴቶቼ ተሰቅለዋል?","privacyAnswer":"አይ ስሌቱ በዚህ አሳሽ ውስጥ ይሰራል; \nእሴቶቹ አልተሰቀሉም ወይም አልተቀመጡም.","fields":{"mode":"ስሌት","momentumMode":"ጠቅላላ ሞመንተም ብቻ","collisionMode":"ግጭት ሞዴል","mass1":"ነገር 1 ብዛት","mass2":"ነገር 2 ብዛት","massUnit":"የጅምላ አሃድ","kilograms":"ኪሎ ግራም (ኪግ)","grams":"ግራም (ሰ)","tonnes":"ሜትሪክ ቶን (ቲ)","velocity1":"ነገር 1 የመጀመሪያ ፍጥነት","velocity2":"ነገር 2 የመጀመሪያ ፍጥነት","speedUnit":"የፍጥነት መለኪያ","metersPerSecond":"ሜትር በሰከንድ (ሜ/ሰ)","kilometersPerHour":"ኪሎሜትሮች በሰዓት (ኪሜ/ሰ)","feetPerSecond":"ጫማ በሰከንድ (ጫማ በሰከንድ)","restitution":"የመመለሻ ዋጋ (0–1)","accuracyNote":"አንድ-ልኬት ክላሲካል ሞዴል. \nአዎንታዊ እና አሉታዊ ፍጥነቶች አቅጣጫ ያሳያሉ. \nግጭቶች እንደ ተገለሉ ይወሰዳሉ፡ ምንም ውጫዊ ግፊት፣ መዞር፣ የተበላሸ ዝርዝር ወይም አንጻራዊ ተጽዕኖዎች አልተቀረጹም። \nየ 1 እሴት ተስማሚ ላስቲክ ነው; \n0 ፍጹም የማይበገር ነው። \nይህ ትምህርታዊ ግምት እንጂ የምህንድስና ወይም የደህንነት ግምገማ አይደለም።"},"actions":{"calculate":"አስላ","reset":"ግልጽ","copy":"ውጤት ቅዳ","example":"እኩል የጅምላ ግጭት ይሞክሩ","result":"የሞመንተም ውጤት"},"messages":{"calculated":"ስሌት ዝግጁ ነው።","checkInputs":"ሁለት አዎንታዊ ብዛት፣ ትክክለኛ የተፈረሙ ፍጥነቶች፣ የሚደገፉ ክፍሎችን እና የመመለሻ ዋጋ ከ0 እስከ 1 ያስገቡ።","momentumBefore":"ከግጭት በፊት ያለው አጠቃላይ ፍጥነት","kineticEnergyBefore":"ከግጭት በፊት አጠቃላይ የእንቅስቃሴ ኃይል","finalVelocity1":"ነገር 1 የመጨረሻ ፍጥነት","finalVelocity2":"ነገር 2 የመጨረሻ ፍጥነት","momentumAfter":"አጠቃላይ ከግጭት በኋላ","kineticEnergyAfter":"ከግጭት በኋላ አጠቃላይ የእንቅስቃሴ ኃይል","energyLoss":"የኪነቲክ ሃይል በአምሳያው ውስጥ ተለወጠ ወይም ጠፍቷል"},"additionalFaqs":[{"question":"አሉታዊ ፍጥነት ምን ማለት ነው?","answer":"ዕቃው ከመረጡት አዎንታዊ አቅጣጫ ወደ ተቃራኒው አቅጣጫ ይንቀሳቀሳል ማለት ነው። \nሁለቱንም ፍጥነቶች በሚያስገቡበት ጊዜ ምልክቱን ያስቀምጡ; \nአጠቃላይ ፍጥነትን እና የግጭቱን ውጤት ይነካል ።"},{"question":"የመመለሻ ብዛት ምን ማለት ነው?","answer":"ከተጠጋው ፍጥነት ጋር ሲነፃፀር ከአንድ-ልኬት ተጽእኖ በኋላ ያለውን አንጻራዊ የመለያ ፍጥነት ይገልጻል። \nዜሮ ሞዴሎች ፍጹም የማይበገር ግጭት; \nአንድ ተስማሚ የመለጠጥ ግጭትን ይቀርፃል። \nእውነተኛ ቁሳቁሶች በተጽዕኖ ሁኔታዎች ሊለያዩ ይችላሉ."},{"question":"በእያንዳንዱ ግጭት ውስጥ ፍጥነት ይጠበቃል?","answer":"አጠቃላይ ሞመንተም በዚህ ሞዴል የተጠበቀው ባለሁለት ነገር ስርዓት ምንም የተጣራ ውጫዊ ግፊት ከሌለው ነው። \nካልኩሌተሩ በፊት እና በኋላ ዋጋዎችን ያሳያል ስለዚህ እነሱን ማወዳደር ይችላሉ።"},{"question":"ይህ ካልኩሌተር የማዕዘን ወይም የሚሽከረከሩ ግጭቶችን ይሸፍናል?","answer":"አይደለም እንቅስቃሴን የሚመስለው በአንድ ቀጥተኛ መስመር ብቻ ነው። \nማዕዘኖችን፣ ማሽከርከርን፣ የነገር ቅርጽን፣ ድምጽን፣ የሙቀት ዝርዝሮችን ወይም መበላሸትን አይሰላም።"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"gu":{"copyLanguage":"gu","name":"મોમેન્ટમ કેલ્ક્યુલેટર","title":"મોમેન્ટમ કેલ્ક્યુલેટર ફ્રી | UsefulVerse","description":"એક-પરિમાણીય ગતિની ગણતરી કરો અથવા હસ્તાક્ષરિત ગતિ સાથે બે-ઓબ્જેક્ટ અથડામણનું મોડેલ બનાવો. \nમફત અને સ્થાનિક.","intro":"એક લીટી સાથે આગળ વધતા બે પદાર્થો માટે કુલ વેગ શોધો અથવા અથડામણ પછી તેમની ઝડપનો અંદાજ કાઢો. \nદરેક દિશાને સકારાત્મક અથવા નકારાત્મક વેગ સાથે સેટ કરો અને 0 થી 1 સુધી પુનઃપ્રાપ્તિનો ગુણાંક પસંદ કરો.","howQuestion":"તમે વેગ અને અથડામણની ઝડપની ગણતરી કેવી રીતે કરશો?","howAnswer":"મોમેન્ટમ એ સામૂહિક ગણો વેગ છે, p = mv, અને કુલ એ બંને ઑબ્જેક્ટ માટે સહી કરેલ સરવાળો છે. \nએક-પરિમાણીય અથડામણ માટે, આ કેલ્ક્યુલેટર દરેક અંતિમ વેગનો અંદાજ કાઢવા માટે પુનઃસ્થાપન ગુણાંકનો ઉપયોગ કરે છે. \nઉદાહરણ તરીકે, આદર્શ સ્થિતિસ્થાપક અથડામણમાં +2 m/s અને −1 m/s વિનિમય ગતિએ આગળ વધી રહેલા સમાન 1 kg માસ, જ્યારે કુલ વેગ 1 kg·m/s રહે છે.","privacyQuestion":"શું મારા મૂલ્યો અપલોડ થયા છે?","privacyAnswer":"નંબર. આ બ્રાઉઝરમાં ગણતરી ચાલે છે; \nમૂલ્યો અપલોડ અથવા સાચવેલ નથી.","fields":{"mode":"ગણતરી","momentumMode":"કુલ મોમેન્ટમ માત્ર","collisionMode":"મોડેલ અથડામણ","mass1":"ઑબ્જેક્ટ 1 સમૂહ","mass2":"ઑબ્જેક્ટ 2 સમૂહ","massUnit":"માસ યુનિટ","kilograms":"કિલોગ્રામ (કિલો)","grams":"ગ્રામ (જી)","tonnes":"મેટ્રિક ટન (ટી)","velocity1":"ઑબ્જેક્ટ 1 પ્રારંભિક વેગ","velocity2":"ઑબ્જેક્ટ 2 પ્રારંભિક વેગ","speedUnit":"વેલોસિટી યુનિટ","metersPerSecond":"મીટર પ્રતિ સેકન્ડ (m/s)","kilometersPerHour":"કિલોમીટર પ્રતિ કલાક (km/h)","feetPerSecond":"ફીટ પ્રતિ સેકન્ડ (ફીટ/સે)","restitution":"વળતરનો ગુણાંક (0–1)","accuracyNote":"વન-ડાયમેન્શનલ ક્લાસિકલ મોડલ. \nહકારાત્મક અને નકારાત્મક વેગ દિશા દર્શાવે છે. \nઅથડામણને અલગ તરીકે ગણવામાં આવે છે: કોઈ બાહ્ય આવેગ, પરિભ્રમણ, વિરૂપતાની વિગતો અથવા સાપેક્ષ અસરોનું મોડેલિંગ કરવામાં આવતું નથી. \n1 નું મૂલ્ય આદર્શ સ્થિતિસ્થાપક છે; \n0 સંપૂર્ણપણે અસ્થિર છે. \nઆ એક શૈક્ષણિક અંદાજ છે, એન્જિનિયરિંગ અથવા સલામતી મૂલ્યાંકન નથી."},"actions":{"calculate":"ગણતરી કરો","reset":"સાફ કરો","copy":"પરિણામની નકલ કરો","example":"સમાન સમૂહ અથડામણ કરવાનો પ્રયાસ કરો","result":"મોમેન્ટમ પરિણામ"},"messages":{"calculated":"ગણતરી તૈયાર.","checkInputs":"બે સકારાત્મક સમૂહ, માન્ય હસ્તાક્ષરિત વેગ, સમર્થિત એકમો અને 0 થી 1 સુધીનું વળતર મૂલ્ય દાખલ કરો.","momentumBefore":"અથડામણ પહેલાની કુલ ગતિ","kineticEnergyBefore":"અથડામણ પહેલા કુલ ગતિ ઊર્જા","finalVelocity1":"ઑબ્જેક્ટ 1 અંતિમ વેગ","finalVelocity2":"ઑબ્જેક્ટ 2 અંતિમ વેગ","momentumAfter":"અથડામણ પછી કુલ ગતિ","kineticEnergyAfter":"અથડામણ પછી કુલ ગતિ ઊર્જા","energyLoss":"મોડેલમાં ગતિ ઊર્જા રૂપાંતરિત અથવા ખોવાઈ ગઈ"},"additionalFaqs":[{"question":"નકારાત્મક વેગનો અર્થ શું થાય છે?","answer":"તેનો અર્થ એ છે કે ઑબ્જેક્ટ તમે પસંદ કરેલી સકારાત્મક દિશામાંથી વિરુદ્ધ દિશામાં આગળ વધે છે. \nબંને વેગ દાખલ કરતી વખતે ચિહ્ન રાખો; \nતે કુલ વેગ અને અથડામણના પરિણામને અસર કરે છે."},{"question":"પુનઃપ્રાપ્તિના ગુણાંકનો અર્થ શું થાય છે?","answer":"તે નજીક આવતી ઝડપની સરખામણીમાં એક-પરિમાણીય અસર પછી સંબંધિત વિભાજિત ગતિનું વર્ણન કરે છે. \nશૂન્ય મૉડલ્સ સંપૂર્ણપણે અસ્થિર અથડામણ; \nએક મોડેલ આદર્શ સ્થિતિસ્થાપક અથડામણ. \nવાસ્તવિક સામગ્રી અસરની પરિસ્થિતિઓ સાથે બદલાઈ શકે છે."},{"question":"શું દરેક અથડામણમાં વેગ સાચવવામાં આવે છે?","answer":"જ્યારે બે-ઓબ્જેક્ટ સિસ્ટમમાં કોઈ ચોખ્ખો બાહ્ય આવેગ નથી ત્યારે આ મોડેલમાં કુલ વેગ સાચવવામાં આવે છે. \nકેલ્ક્યુલેટર પહેલા અને પછીના મૂલ્યો બતાવે છે જેથી તમે તેમની સરખામણી કરી શકો."},{"question":"શું આ કેલ્ક્યુલેટર કોણીય અથવા ફરતી અથડામણોને આવરી લે છે?","answer":"નંબર. તે માત્ર એક સીધી રેખા પર ગતિનું મોડેલ કરે છે. \nતે ખૂણા, પરિભ્રમણ, પદાર્થ આકાર, ધ્વનિ, ગરમીની વિગતો અથવા વિરૂપતાની ગણતરી કરતું નથી."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"}});
